-- SOURCE: 20261119090100_foundation.sql
-- SwapFix 1/8: private helper schema, accounts, technician profiles, notifications.
--
-- Security model used by every migration in this folder:
--   * Exposed tables have RLS and receive SELECT grants only (see 8/8).
--   * Every write goes through a swapfix_private.api_* SECURITY DEFINER function that
--     derives the actor from auth.uid() and re-checks ownership and state under row locks.
--   * swapfix_private is not exposed by PostgREST. Clients reach it only through the
--     SECURITY INVOKER public.sf_* wrappers generated in 8/8.
--   * Business failures use SQLSTATE SF401/SF403/SF404/SF409/SF422 with a user-safe message.

create schema if not exists swapfix_private;
revoke all on schema swapfix_private from public;
grant usage on schema swapfix_private to anon, authenticated, service_role;
comment on schema swapfix_private is 'SwapFix internals. Never add this schema to the Data API exposed schemas.';

create function swapfix_private.fail(p_code text, p_message text) returns void
language plpgsql set search_path = '' as $$
begin
    raise exception using errcode = p_code, message = p_message;
end;
$$;

create function swapfix_private.require_user() returns uuid
language plpgsql stable set search_path = '' as $$
declare
    v_user uuid := auth.uid();
begin
    if v_user is null then
        perform swapfix_private.fail('SF401', 'Sign in to continue.');
    end if;
    return v_user;
end;
$$;

create function swapfix_private.clean_text(p_value text, p_label text, p_min integer, p_max integer) returns text
language plpgsql set search_path = '' as $$
declare
    v_text text := btrim(coalesce(p_value, ''), E' \t\r\n');
begin
    if char_length(v_text) < p_min then
        perform swapfix_private.fail('SF422', p_label || ' is required.');
    end if;
    if char_length(v_text) > p_max then
        perform swapfix_private.fail('SF422', p_label || ' must be ' || p_max || ' characters or fewer.');
    end if;
    return v_text;
end;
$$;

create function swapfix_private.clean_list(p_values text[], p_label text, p_max_items integer, p_max_length integer) returns text[]
language plpgsql set search_path = '' as $$
declare
    v_items text[];
begin
    select coalesce(array_agg(item order by position), '{}') into v_items
    from (
        select distinct on (lower(btrim(value))) btrim(value) as item, position
        from unnest(coalesce(p_values, '{}'::text[])) with ordinality as source(value, position)
        where btrim(coalesce(value, '')) <> ''
        order by lower(btrim(value)), position
    ) unique_items;
    if cardinality(v_items) > p_max_items then
        perform swapfix_private.fail('SF422', p_label || ' can contain at most ' || p_max_items || ' items.');
    end if;
    if exists (select 1 from unnest(v_items) item where char_length(item) > p_max_length) then
        perform swapfix_private.fail('SF422', p_label || ' items must be ' || p_max_length || ' characters or fewer.');
    end if;
    return v_items;
end;
$$;

create function swapfix_private.clean_money(p_value numeric, p_label text, p_minimum numeric) returns numeric
language plpgsql set search_path = '' as $$
begin
    if p_value is null or p_value < p_minimum or p_value >= 10000000000 then
        perform swapfix_private.fail('SF422', p_label || ' must be between ' || p_minimum || ' and 9,999,999,999.99.');
    end if;
    if p_value <> round(p_value, 2) then
        perform swapfix_private.fail('SF422', p_label || ' can have at most two decimal places.');
    end if;
    return round(p_value, 2);
end;
$$;

create function swapfix_private.valid_photo_paths(p_paths text[], p_owner uuid, p_max integer) returns boolean
language sql immutable set search_path = '' as $$
    select coalesce(cardinality(p_paths), 0) <= p_max
       and not exists (
            select 1 from unnest(coalesce(p_paths, '{}'::text[])) as path
            where path is null or path !~ ('^' || p_owner::text || '/[a-f0-9]{32}\.(jpg|png|webp)$')
       )
       and (select count(*) = count(distinct path) from unnest(coalesce(p_paths, '{}'::text[])) as path);
$$;

create function swapfix_private.clean_photo_paths(p_paths text[], p_owner uuid, p_max integer) returns text[]
language plpgsql set search_path = '' as $$
begin
    if not swapfix_private.valid_photo_paths(p_paths, p_owner, p_max) then
        perform swapfix_private.fail('SF422', 'Photos must be your own uploads, at most ' || p_max || ' per record.');
    end if;
    return coalesce(p_paths, '{}'::text[]);
end;
$$;

-- Search helpers run inside SECURITY INVOKER read functions, including for anon.
create function swapfix_private.like_pattern(p_value text) returns text
language sql immutable set search_path = '' as $$
    select '%' || replace(replace(replace(btrim(p_value), '\', '\\'), '%', '\%'), '_', '\_') || '%';
$$;

create function swapfix_private.prefix_tsquery(p_value text) returns tsquery
language sql immutable set search_path = '' as $$
    select coalesce(
        (select to_tsquery('simple'::regconfig, string_agg(quote_literal(term) || ':*', ' & '))
         from unnest(regexp_split_to_array(lower(left(coalesce(p_value, ''), 100)), '[^[:alnum:]]+')) as term
         where term <> ''),
        ''::tsquery
    );
$$;

create function swapfix_private.touch_updated_at() returns trigger
language plpgsql set search_path = '' as $$
begin
    new.updated_at := now();
    return new;
end;
$$;

create function swapfix_private.forbid_update() returns trigger
language plpgsql set search_path = '' as $$
begin
    raise exception using errcode = 'SF409', message = 'This record is permanent and cannot be changed.';
end;
$$;

-- Accounts. Only non-sensitive card fields live in profiles because it is publicly readable.
create table public.profiles (
    id uuid primary key references auth.users (id) on delete cascade,
    account_type text not null check (account_type in ('customer', 'technician')),
    display_name text not null check (char_length(display_name) between 2 and 80),
    avatar_path text,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint profiles_avatar_owned check (avatar_path is null or swapfix_private.valid_photo_paths(array[avatar_path], id, 1))
);
create trigger profiles_touch before update on public.profiles
for each row execute function swapfix_private.touch_updated_at();

create table public.profile_private (
    user_id uuid primary key references public.profiles (id) on delete cascade,
    location text not null default '' check (char_length(location) <= 120),
    email_notifications boolean not null default false,
    updated_at timestamptz not null default now()
);
create trigger profile_private_touch before update on public.profile_private
for each row execute function swapfix_private.touch_updated_at();

create table public.technician_profiles (
    user_id uuid primary key references public.profiles (id) on delete cascade,
    headline text not null default '' check (char_length(headline) <= 120),
    bio text not null default '' check (char_length(bio) <= 2000),
    location text not null default '' check (char_length(location) <= 120),
    service_area text not null default '' check (char_length(service_area) <= 200),
    available_hours text not null default '' check (char_length(available_hours) <= 200),
    specialties text[] not null default '{}',
    supported_brands text[] not null default '{}',
    supported_models text[] not null default '{}',
    rating_average numeric(3, 2) not null default 0 check (rating_average between 0 and 5),
    rating_count integer not null default 0 check (rating_count >= 0),
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);
create index technician_profiles_rating_idx on public.technician_profiles (rating_average desc, rating_count desc);
create index technician_profiles_specialties_idx on public.technician_profiles using gin (specialties);
create index technician_profiles_brands_idx on public.technician_profiles using gin (supported_brands);
create trigger technician_profiles_touch before update on public.technician_profiles
for each row execute function swapfix_private.touch_updated_at();

create function swapfix_private.require_profile() returns uuid
language plpgsql stable set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_user();
begin
    if not exists (select 1 from public.profiles where id = v_user) then
        perform swapfix_private.fail('SF403', 'Finish setting up your account first.');
    end if;
    return v_user;
end;
$$;

-- Authorization reads the stored account type, never JWT or user metadata.
create function swapfix_private.require_technician() returns uuid
language plpgsql stable set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_user();
begin
    if not exists (select 1 from public.profiles where id = v_user and account_type = 'technician') then
        perform swapfix_private.fail('SF403', 'Only technician accounts can do this.');
    end if;
    return v_user;
end;
$$;

-- Notifications and the optional email outbox.
create table public.notifications (
    id uuid primary key default gen_random_uuid(),
    recipient_id uuid not null references public.profiles (id) on delete cascade,
    actor_id uuid references public.profiles (id) on delete set null,
    kind text not null check (kind in (
        'message', 'trade_offer', 'trade_counter', 'trade_accepted', 'trade_declined', 'trade_update',
        'repair_request', 'quotation_sent', 'quotation_accepted', 'quotation_declined',
        'added_cost_requested', 'added_cost_accepted', 'added_cost_declined', 'repair_status', 'review'
    )),
    title text not null check (char_length(title) between 1 and 160),
    body text not null default '' check (char_length(body) <= 400),
    link_path text not null check (link_path ~ '^/[A-Za-z0-9/_-]*$'),
    related_type text not null check (related_type in ('listing', 'exchange', 'offer', 'repair', 'conversation')),
    related_id uuid not null,
    read_at timestamptz,
    created_at timestamptz not null default now()
);
create index notifications_recipient_idx on public.notifications (recipient_id, created_at desc);
create index notifications_unread_idx on public.notifications (recipient_id) where read_at is null;
create index notifications_actor_idx on public.notifications (actor_id);
-- One unread message notification per conversation keeps busy chats from flooding the list.
create unique index notifications_unread_message_idx on public.notifications (recipient_id, related_id)
    where kind = 'message' and read_at is null;

create table public.mail_outbox (
    id uuid primary key default gen_random_uuid(),
    notification_id uuid not null unique references public.notifications (id) on delete cascade,
    status text not null default 'pending' check (status in ('pending', 'sending', 'sent', 'failed')),
    attempts integer not null default 0 check (attempts >= 0),
    claimed_at timestamptz,
    sent_at timestamptz,
    created_at timestamptz not null default now()
);
create index mail_outbox_claim_idx on public.mail_outbox (status, created_at);

create function swapfix_private.notify(
    p_recipient uuid, p_kind text, p_title text, p_body text, p_link text, p_related_type text, p_related_id uuid
) returns void
language plpgsql set search_path = '' as $$
declare
    v_actor uuid := auth.uid();
    v_id uuid;
    v_body text := left(coalesce(p_body, ''), 400);
begin
    if p_recipient is null or p_recipient = v_actor then
        return;
    end if;
    if p_kind = 'message' then
        update public.notifications
        set body = v_body, title = p_title, actor_id = v_actor, created_at = now()
        where recipient_id = p_recipient and related_id = p_related_id and kind = 'message' and read_at is null;
        if found then
            return;
        end if;
    end if;
    insert into public.notifications (recipient_id, actor_id, kind, title, body, link_path, related_type, related_id)
    values (p_recipient, v_actor, p_kind, left(p_title, 160), v_body, p_link, p_related_type, p_related_id)
    returning id into v_id;
    if exists (select 1 from public.profile_private where user_id = p_recipient and email_notifications) then
        insert into public.mail_outbox (notification_id) values (v_id);
    end if;
end;
$$;

-- Account API
create function swapfix_private.api_create_profile(p_account_type text, p_display_name text, p_location text default '')
returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_user();
    v_name text := swapfix_private.clean_text(p_display_name, 'Name', 2, 80);
    v_location text := swapfix_private.clean_text(p_location, 'Location', 0, 120);
begin
    if p_account_type is null or p_account_type not in ('customer', 'technician') then
        perform swapfix_private.fail('SF422', 'Choose a customer or technician account.');
    end if;
    insert into public.profiles (id, account_type, display_name)
    values (v_user, p_account_type, v_name)
    on conflict (id) do nothing;
    if not found then
        perform swapfix_private.fail('SF409', 'This account is already set up.');
    end if;
    insert into public.profile_private (user_id, location) values (v_user, v_location);
    if p_account_type = 'technician' then
        insert into public.technician_profiles (user_id, location) values (v_user, v_location);
    end if;
    return jsonb_build_object('id', v_user, 'account_type', p_account_type);
end;
$$;

create function swapfix_private.api_update_profile(
    p_display_name text, p_location text, p_avatar_path text default null,
    p_clear_avatar boolean default false, p_email_notifications boolean default false
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_profile();
    v_name text := swapfix_private.clean_text(p_display_name, 'Name', 2, 80);
    v_location text := swapfix_private.clean_text(p_location, 'Location', 0, 120);
    v_previous text;
    v_next text;
begin
    select avatar_path into v_previous from public.profiles where id = v_user for update;
    v_next := case when p_clear_avatar then null else coalesce(p_avatar_path, v_previous) end;
    if v_next is not null then
        perform swapfix_private.clean_photo_paths(array[v_next], v_user, 1);
    end if;
    update public.profiles set display_name = v_name, avatar_path = v_next where id = v_user;
    update public.profile_private
    set location = v_location, email_notifications = coalesce(p_email_notifications, false)
    where user_id = v_user;
    return jsonb_build_object(
        'avatar_path', v_next,
        'replaced_avatar_path', case when v_previous is distinct from v_next then v_previous end
    );
end;
$$;

create function swapfix_private.api_save_technician_profile(
    p_headline text, p_bio text, p_location text, p_service_area text, p_available_hours text,
    p_specialties text[], p_supported_brands text[], p_supported_models text[]
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_technician();
    v_specialties text[] := swapfix_private.clean_list(p_specialties, 'Specialties', 20, 60);
begin
    if cardinality(v_specialties) = 0 then
        perform swapfix_private.fail('SF422', 'Add at least one repair specialty.');
    end if;
    insert into public.technician_profiles (
        user_id, headline, bio, location, service_area, available_hours, specialties, supported_brands, supported_models
    ) values (
        v_user,
        swapfix_private.clean_text(p_headline, 'Headline', 0, 120),
        swapfix_private.clean_text(p_bio, 'About', 0, 2000),
        swapfix_private.clean_text(p_location, 'Location', 2, 120),
        swapfix_private.clean_text(p_service_area, 'Service area', 2, 200),
        swapfix_private.clean_text(p_available_hours, 'Available hours', 2, 200),
        v_specialties,
        swapfix_private.clean_list(p_supported_brands, 'Brands', 30, 60),
        swapfix_private.clean_list(p_supported_models, 'Models', 60, 80)
    )
    on conflict (user_id) do update set
        headline = excluded.headline, bio = excluded.bio, location = excluded.location,
        service_area = excluded.service_area, available_hours = excluded.available_hours,
        specialties = excluded.specialties, supported_brands = excluded.supported_brands,
        supported_models = excluded.supported_models;
    return jsonb_build_object('id', v_user);
end;
$$;

-- Notification API
create function swapfix_private.api_mark_notification_read(p_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_user();
    v_link text;
begin
    update public.notifications
    set read_at = coalesce(read_at, now())
    where id = p_id and recipient_id = v_user
    returning link_path into v_link;
    if v_link is null then
        perform swapfix_private.fail('SF404', 'Notification not found.');
    end if;
    return jsonb_build_object('link_path', v_link);
end;
$$;

create function swapfix_private.api_mark_all_notifications_read() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_user();
    v_count integer;
begin
    update public.notifications set read_at = now() where recipient_id = v_user and read_at is null;
    get diagnostics v_count = row_count;
    return jsonb_build_object('updated', v_count);
end;
$$;

-- Email worker API. Execute is granted to service_role only (see 8/8).
create function swapfix_private.api_mail_claim(p_limit integer default 20)
returns table (outbox_id uuid, email text, display_name text, title text, body text, link_path text)
language plpgsql security definer set search_path = '' as $$
begin
    return query
    with claimed as (
        update public.mail_outbox o
        set status = 'sending', attempts = o.attempts + 1, claimed_at = now()
        where o.id in (
            select candidate.id from public.mail_outbox candidate
            where candidate.attempts < 5
              and (candidate.status = 'pending'
                   or (candidate.status = 'sending' and candidate.claimed_at < now() - interval '15 minutes'))
            order by candidate.created_at
            limit least(greatest(coalesce(p_limit, 20), 1), 50)
            for update skip locked
        )
        returning o.id, o.notification_id
    )
    select c.id, u.email::text, p.display_name, n.title, n.body, n.link_path
    from claimed c
    join public.notifications n on n.id = c.notification_id
    join public.profiles p on p.id = n.recipient_id
    join auth.users u on u.id = n.recipient_id
    where u.email is not null;
end;
$$;

create function swapfix_private.api_mail_mark(p_outbox_id uuid, p_sent boolean) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
    update public.mail_outbox
    set status = case when p_sent then 'sent' when attempts >= 5 then 'failed' else 'pending' end,
        sent_at = case when p_sent then now() end
    where id = p_outbox_id and status = 'sending';
    return jsonb_build_object('updated', found);
end;
$$;


-- SOURCE: 20261119090200_marketplace.sql
-- SwapFix 2/8: Buy & Sell listings.

create table public.product_listings (
    id uuid primary key default gen_random_uuid(),
    owner_id uuid not null references public.profiles (id),
    title text not null check (char_length(title) between 3 and 150),
    description text not null check (char_length(description) between 1 and 4000),
    category text not null check (category in ('cellphone', 'tablet', 'laptop', 'accessory', 'spare_part')),
    brand text not null check (char_length(brand) between 1 and 60),
    model text not null default '' check (char_length(model) <= 80),
    condition text not null check (condition in ('new', 'like_new', 'good', 'fair', 'for_parts')),
    known_defects text not null default '' check (char_length(known_defects) <= 2000),
    price numeric(12, 2) not null check (price >= 0),
    location text not null check (char_length(location) between 2 and 120),
    photo_paths text[] not null default '{}',
    status text not null default 'available' check (status in ('available', 'reserved', 'sold', 'removed')),
    status_changed_at timestamptz not null default now(),
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    search tsvector generated always as (
        to_tsvector('simple'::regconfig, title || ' ' || brand || ' ' || model || ' ' || description)
    ) stored,
    constraint product_listings_photos_owned check (swapfix_private.valid_photo_paths(photo_paths, owner_id, 8))
);
create index product_listings_owner_idx on public.product_listings (owner_id, created_at desc);
create index product_listings_browse_idx on public.product_listings (status, created_at desc);
create index product_listings_category_idx on public.product_listings (status, category, created_at desc);
create index product_listings_price_idx on public.product_listings (status, price);
create index product_listings_brand_idx on public.product_listings (lower(brand));
create index product_listings_search_idx on public.product_listings using gin (search);
create trigger product_listings_touch before update on public.product_listings
for each row execute function swapfix_private.touch_updated_at();

create function swapfix_private.api_save_listing(
    p_id uuid, p_title text, p_description text, p_category text, p_brand text, p_model text,
    p_condition text, p_known_defects text, p_price numeric, p_location text, p_photo_paths text[]
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_profile();
    v_title text := swapfix_private.clean_text(p_title, 'Title', 3, 150);
    v_description text := swapfix_private.clean_text(p_description, 'Description', 1, 4000);
    v_brand text := swapfix_private.clean_text(p_brand, 'Brand', 1, 60);
    v_model text := swapfix_private.clean_text(p_model, 'Model', 0, 80);
    v_defects text := swapfix_private.clean_text(p_known_defects, 'Known defects', 0, 2000);
    v_location text := swapfix_private.clean_text(p_location, 'Location', 2, 120);
    v_price numeric := swapfix_private.clean_money(p_price, 'Price', 0);
    v_photos text[] := swapfix_private.clean_photo_paths(p_photo_paths, v_user, 8);
    v_current public.product_listings;
    v_id uuid;
begin
    if p_category is null or p_category not in ('cellphone', 'tablet', 'laptop', 'accessory', 'spare_part') then
        perform swapfix_private.fail('SF422', 'Choose a valid category.');
    end if;
    if p_condition is null or p_condition not in ('new', 'like_new', 'good', 'fair', 'for_parts') then
        perform swapfix_private.fail('SF422', 'Choose a valid condition.');
    end if;
    if p_id is null then
        insert into public.product_listings (
            owner_id, title, description, category, brand, model, condition, known_defects, price, location, photo_paths
        ) values (
            v_user, v_title, v_description, p_category, v_brand, v_model, p_condition, v_defects, v_price, v_location, v_photos
        ) returning id into v_id;
        return jsonb_build_object('id', v_id, 'removed_paths', '[]'::jsonb);
    end if;
    select * into v_current from public.product_listings where id = p_id for update;
    if not found or v_current.owner_id <> v_user then
        perform swapfix_private.fail('SF404', 'Listing not found.');
    end if;
    if v_current.status not in ('available', 'reserved') then
        perform swapfix_private.fail('SF409', 'Sold or removed listings cannot be edited.');
    end if;
    update public.product_listings set
        title = v_title, description = v_description, category = p_category, brand = v_brand, model = v_model,
        condition = p_condition, known_defects = v_defects, price = v_price, location = v_location, photo_paths = v_photos
    where id = p_id;
    return jsonb_build_object('id', p_id, 'removed_paths', (
        select coalesce(jsonb_agg(path), '[]'::jsonb) from unnest(v_current.photo_paths) as path where path <> all (v_photos)
    ));
end;
$$;

create function swapfix_private.api_set_listing_status(p_id uuid, p_status text, p_expected_status text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_profile();
    v_current public.product_listings;
begin
    select * into v_current from public.product_listings where id = p_id for update;
    if not found or v_current.owner_id <> v_user then
        perform swapfix_private.fail('SF404', 'Listing not found.');
    end if;
    if v_current.status is distinct from p_expected_status then
        perform swapfix_private.fail('SF409', 'This listing changed. Refresh and try again.');
    end if;
    if not ((v_current.status, p_status) in (
        ('available', 'reserved'), ('available', 'sold'), ('available', 'removed'),
        ('reserved', 'available'), ('reserved', 'sold'), ('reserved', 'removed')
    )) then
        perform swapfix_private.fail('SF409', 'That availability change is not allowed.');
    end if;
    update public.product_listings set status = p_status, status_changed_at = now() where id = p_id;
    return jsonb_build_object('id', p_id, 'status', p_status);
end;
$$;

-- Public browsing. SECURITY INVOKER: RLS still applies.
create function public.sf_search_listings(
    p_query text default null, p_category text default null, p_brand text default null,
    p_condition text default null, p_min_price numeric default null, p_max_price numeric default null,
    p_location text default null, p_sort text default 'newest', p_limit integer default 24, p_offset integer default 0
) returns jsonb
language sql stable security invoker set search_path = '' as $$
    with filtered as (
        select l.* from public.product_listings l
        where l.status in ('available', 'reserved')
          and (nullif(btrim(p_query), '') is null or l.search @@ swapfix_private.prefix_tsquery(p_query))
          and (nullif(p_category, '') is null or l.category = p_category)
          and (nullif(btrim(p_brand), '') is null or lower(l.brand) = lower(btrim(p_brand)))
          and (nullif(p_condition, '') is null or l.condition = p_condition)
          and (p_min_price is null or l.price >= p_min_price)
          and (p_max_price is null or l.price <= p_max_price)
          and (nullif(btrim(p_location), '') is null or l.location ilike swapfix_private.like_pattern(p_location))
    ), page as (
        select f.*, row_number() over (
            order by
                case when p_sort = 'price_asc' then f.price end asc nulls last,
                case when p_sort = 'price_desc' then f.price end desc nulls last,
                f.created_at desc, f.id
        ) as position
        from filtered f
        order by position
        limit least(greatest(coalesce(p_limit, 24), 1), 48)
        offset least(greatest(coalesce(p_offset, 0), 0), 10000)
    )
    select jsonb_build_object(
        'total', (select count(*) from filtered),
        'items', coalesce((
            select jsonb_agg(jsonb_build_object(
                'id', p.id, 'title', p.title, 'category', p.category, 'brand', p.brand, 'model', p.model,
                'condition', p.condition, 'known_defects', p.known_defects, 'price', p.price, 'location', p.location,
                'photo_paths', p.photo_paths, 'status', p.status, 'created_at', p.created_at,
                'owner', jsonb_build_object('id', o.id, 'display_name', o.display_name, 'avatar_path', o.avatar_path)
            ) order by p.position)
            from page p join public.profiles o on o.id = p.owner_id
        ), '[]'::jsonb)
    );
$$;


-- SOURCE: 20261119090300_exchange.sql
-- SwapFix 3/8: exchange listings, trade offers and immutable counteroffer history.
--
-- Lifecycle: exchange open -> agreed -> completed. Acceptance (agreed) and physical handover
-- (completed) are separate events. While agreed, other offers stay pending but cannot be
-- acted on; if the agreement is cancelled the exchange reopens and they become actionable.
-- Lock order is always exchange row first, then offer row.

create table public.exchange_listings (
    id uuid primary key default gen_random_uuid(),
    owner_id uuid not null references public.profiles (id),
    title text not null check (char_length(title) between 3 and 150),
    description text not null default '' check (char_length(description) <= 4000),
    category text not null check (category in ('cellphone', 'tablet', 'laptop', 'accessory', 'spare_part')),
    brand text not null check (char_length(brand) between 1 and 60),
    model text not null default '' check (char_length(model) <= 80),
    condition text not null check (condition in ('new', 'like_new', 'good', 'fair', 'for_parts')),
    known_defects text not null default '' check (char_length(known_defects) <= 2000),
    location text not null check (char_length(location) between 2 and 120),
    photo_paths text[] not null default '{}',
    wanted_item text not null check (char_length(wanted_item) between 2 and 200),
    wanted_details text not null default '' check (char_length(wanted_details) <= 2000),
    cash_preference text not null default 'none'
        check (cash_preference in ('none', 'owner_may_add', 'offerer_may_add', 'either')),
    status text not null default 'open' check (status in ('open', 'agreed', 'completed', 'removed')),
    accepted_offer_id uuid,
    completed_at timestamptz,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    search tsvector generated always as (
        to_tsvector('simple'::regconfig, title || ' ' || brand || ' ' || model || ' ' || wanted_item || ' ' || description)
    ) stored,
    constraint exchange_photos_owned check (swapfix_private.valid_photo_paths(photo_paths, owner_id, 8)),
    constraint exchange_agreed_has_offer check ((status in ('agreed', 'completed')) = (accepted_offer_id is not null)),
    constraint exchange_completed_time check ((status = 'completed') = (completed_at is not null))
);
create index exchange_listings_owner_idx on public.exchange_listings (owner_id, created_at desc);
create index exchange_listings_browse_idx on public.exchange_listings (status, created_at desc);
create index exchange_listings_category_idx on public.exchange_listings (status, category, created_at desc);
create index exchange_listings_brand_idx on public.exchange_listings (lower(brand));
create index exchange_listings_search_idx on public.exchange_listings using gin (search);
create index exchange_listings_accepted_offer_idx on public.exchange_listings (accepted_offer_id);
create trigger exchange_listings_touch before update on public.exchange_listings
for each row execute function swapfix_private.touch_updated_at();

create table public.trade_offers (
    id uuid primary key default gen_random_uuid(),
    exchange_id uuid not null references public.exchange_listings (id),
    offerer_id uuid not null references public.profiles (id),
    owner_id uuid not null references public.profiles (id),
    status text not null default 'pending'
        check (status in ('pending', 'accepted', 'declined', 'withdrawn', 'cancelled', 'completed')),
    current_version integer not null default 1 check (current_version >= 1),
    awaiting_user_id uuid references public.profiles (id),
    accepted_version integer,
    decided_at timestamptz,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint trade_offers_not_self check (offerer_id <> owner_id),
    constraint trade_offers_awaiting check ((status = 'pending') = (awaiting_user_id is not null)),
    constraint trade_offers_awaiting_party check (awaiting_user_id is null or awaiting_user_id in (offerer_id, owner_id)),
    constraint trade_offers_accepted_version check ((status in ('accepted', 'completed')) = (accepted_version is not null))
);
-- The database itself guarantees at most one accepted or completed offer per exchange.
create unique index trade_offers_one_accepted_idx on public.trade_offers (exchange_id)
    where status in ('accepted', 'completed');
create unique index trade_offers_one_active_per_user_idx on public.trade_offers (exchange_id, offerer_id)
    where status in ('pending', 'accepted');
create index trade_offers_exchange_idx on public.trade_offers (exchange_id, created_at desc);
create index trade_offers_offerer_idx on public.trade_offers (offerer_id, created_at desc);
create index trade_offers_owner_idx on public.trade_offers (owner_id, created_at desc);
create index trade_offers_awaiting_idx on public.trade_offers (awaiting_user_id) where awaiting_user_id is not null;
create trigger trade_offers_touch before update on public.trade_offers
for each row execute function swapfix_private.touch_updated_at();

alter table public.exchange_listings
    add constraint exchange_listings_accepted_offer_fkey foreign key (accepted_offer_id) references public.trade_offers (id);

create table public.trade_offer_terms (
    id uuid primary key default gen_random_uuid(),
    offer_id uuid not null references public.trade_offers (id) on delete cascade,
    version integer not null check (version >= 1),
    proposed_by uuid not null references public.profiles (id),
    device_title text not null check (char_length(device_title) between 3 and 150),
    brand text not null check (char_length(brand) between 1 and 60),
    model text not null default '' check (char_length(model) <= 80),
    condition text not null check (condition in ('new', 'like_new', 'good', 'fair', 'for_parts')),
    known_defects text not null default '' check (char_length(known_defects) <= 2000),
    message text not null default '' check (char_length(message) <= 2000),
    cash_amount numeric(12, 2) not null default 0 check (cash_amount >= 0),
    cash_payer text not null default 'none' check (cash_payer in ('none', 'owner', 'offerer')),
    photo_owner_id uuid not null references public.profiles (id),
    photo_paths text[] not null default '{}',
    created_at timestamptz not null default now(),
    unique (offer_id, version),
    constraint trade_terms_cash_payer check ((cash_payer = 'none') = (cash_amount = 0)),
    constraint trade_terms_photos_owned check (swapfix_private.valid_photo_paths(photo_paths, photo_owner_id, 6))
);
create index trade_offer_terms_proposed_by_idx on public.trade_offer_terms (proposed_by);
create index trade_offer_terms_photo_owner_idx on public.trade_offer_terms (photo_owner_id);
create index trade_offer_terms_photos_idx on public.trade_offer_terms using gin (photo_paths);
create trigger trade_offer_terms_immutable before update on public.trade_offer_terms
for each row execute function swapfix_private.forbid_update();

create table public.trade_offer_events (
    id uuid primary key default gen_random_uuid(),
    offer_id uuid not null references public.trade_offers (id) on delete cascade,
    actor_id uuid not null references public.profiles (id),
    event text not null check (event in ('offered', 'countered', 'accepted', 'declined', 'withdrawn', 'cancelled', 'completed')),
    version integer not null,
    note text not null default '' check (char_length(note) <= 1000),
    created_at timestamptz not null default now()
);
create index trade_offer_events_offer_idx on public.trade_offer_events (offer_id, created_at);
create index trade_offer_events_actor_idx on public.trade_offer_events (actor_id);
create trigger trade_offer_events_immutable before update on public.trade_offer_events
for each row execute function swapfix_private.forbid_update();

create function swapfix_private.check_cash(p_amount numeric, p_payer text) returns numeric
language plpgsql set search_path = '' as $$
declare
    v_amount numeric := swapfix_private.clean_money(coalesce(p_amount, 0), 'Cash amount', 0);
begin
    if p_payer is null or p_payer not in ('none', 'owner', 'offerer') then
        perform swapfix_private.fail('SF422', 'Choose who pays the cash amount.');
    end if;
    if (p_payer = 'none') <> (v_amount = 0) then
        perform swapfix_private.fail('SF422', 'Enter a cash amount together with who pays it.');
    end if;
    return v_amount;
end;
$$;

create function swapfix_private.check_condition(p_condition text) returns void
language plpgsql set search_path = '' as $$
begin
    if p_condition is null or p_condition not in ('new', 'like_new', 'good', 'fair', 'for_parts') then
        perform swapfix_private.fail('SF422', 'Choose a valid condition.');
    end if;
end;
$$;

-- Cancels other live offers when a listing leaves the market.
create function swapfix_private.close_pending_offers(p_exchange public.exchange_listings, p_actor uuid, p_note text) returns void
language plpgsql set search_path = '' as $$
declare
    v_offer public.trade_offers;
begin
    for v_offer in
        select * from public.trade_offers where exchange_id = p_exchange.id and status = 'pending' for update
    loop
        update public.trade_offers
        set status = 'cancelled', awaiting_user_id = null, decided_at = now()
        where id = v_offer.id;
        insert into public.trade_offer_events (offer_id, actor_id, event, version, note)
        values (v_offer.id, p_actor, 'cancelled', v_offer.current_version, p_note);
        perform swapfix_private.notify(
            v_offer.offerer_id, 'trade_update', 'Exchange closed', p_exchange.title || ': ' || p_note,
            '/offers/' || v_offer.id, 'offer', v_offer.id
        );
    end loop;
end;
$$;

create function swapfix_private.api_save_exchange(
    p_id uuid, p_title text, p_description text, p_category text, p_brand text, p_model text, p_condition text,
    p_known_defects text, p_location text, p_photo_paths text[], p_wanted_item text, p_wanted_details text,
    p_cash_preference text
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_profile();
    v_title text := swapfix_private.clean_text(p_title, 'Title', 3, 150);
    v_description text := swapfix_private.clean_text(p_description, 'Description', 0, 4000);
    v_brand text := swapfix_private.clean_text(p_brand, 'Brand', 1, 60);
    v_model text := swapfix_private.clean_text(p_model, 'Model', 0, 80);
    v_defects text := swapfix_private.clean_text(p_known_defects, 'Known defects', 0, 2000);
    v_location text := swapfix_private.clean_text(p_location, 'Location', 2, 120);
    v_wanted text := swapfix_private.clean_text(p_wanted_item, 'Wanted gadget', 2, 200);
    v_wanted_details text := swapfix_private.clean_text(p_wanted_details, 'Wanted details', 0, 2000);
    v_photos text[] := swapfix_private.clean_photo_paths(p_photo_paths, v_user, 8);
    v_current public.exchange_listings;
    v_id uuid;
begin
    perform swapfix_private.check_condition(p_condition);
    if p_category is null or p_category not in ('cellphone', 'tablet', 'laptop', 'accessory', 'spare_part') then
        perform swapfix_private.fail('SF422', 'Choose a valid category.');
    end if;
    if p_cash_preference is null or p_cash_preference not in ('none', 'owner_may_add', 'offerer_may_add', 'either') then
        perform swapfix_private.fail('SF422', 'Choose a cash preference.');
    end if;
    if p_id is null then
        insert into public.exchange_listings (
            owner_id, title, description, category, brand, model, condition, known_defects, location,
            photo_paths, wanted_item, wanted_details, cash_preference
        ) values (
            v_user, v_title, v_description, p_category, v_brand, v_model, p_condition, v_defects, v_location,
            v_photos, v_wanted, v_wanted_details, p_cash_preference
        ) returning id into v_id;
        return jsonb_build_object('id', v_id, 'removed_paths', '[]'::jsonb);
    end if;
    select * into v_current from public.exchange_listings where id = p_id for update;
    if not found or v_current.owner_id <> v_user then
        perform swapfix_private.fail('SF404', 'Exchange listing not found.');
    end if;
    if v_current.status <> 'open' then
        perform swapfix_private.fail('SF409', 'Only open exchange listings can be edited.');
    end if;
    update public.exchange_listings set
        title = v_title, description = v_description, category = p_category, brand = v_brand, model = v_model,
        condition = p_condition, known_defects = v_defects, location = v_location, photo_paths = v_photos,
        wanted_item = v_wanted, wanted_details = v_wanted_details, cash_preference = p_cash_preference
    where id = p_id;
    return jsonb_build_object('id', p_id, 'removed_paths', (
        select coalesce(jsonb_agg(path), '[]'::jsonb) from unnest(v_current.photo_paths) as path where path <> all (v_photos)
    ));
end;
$$;

create function swapfix_private.api_remove_exchange(p_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_profile();
    v_exchange public.exchange_listings;
begin
    select * into v_exchange from public.exchange_listings where id = p_id for update;
    if not found or v_exchange.owner_id <> v_user then
        perform swapfix_private.fail('SF404', 'Exchange listing not found.');
    end if;
    if v_exchange.status <> 'open' then
        perform swapfix_private.fail('SF409', 'Cancel the agreement before removing this listing.');
    end if;
    perform swapfix_private.close_pending_offers(v_exchange, v_user, 'The owner removed this listing.');
    update public.exchange_listings set status = 'removed' where id = p_id;
    return jsonb_build_object('id', p_id, 'status', 'removed');
end;
$$;

create function swapfix_private.api_submit_offer(
    p_exchange_id uuid, p_device_title text, p_brand text, p_model text, p_condition text,
    p_known_defects text, p_message text, p_cash_amount numeric, p_cash_payer text, p_photo_paths text[]
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_profile();
    v_title text := swapfix_private.clean_text(p_device_title, 'Gadget name', 3, 150);
    v_brand text := swapfix_private.clean_text(p_brand, 'Brand', 1, 60);
    v_model text := swapfix_private.clean_text(p_model, 'Model', 0, 80);
    v_defects text := swapfix_private.clean_text(p_known_defects, 'Known defects', 0, 2000);
    v_message text := swapfix_private.clean_text(p_message, 'Message', 1, 2000);
    v_cash numeric := swapfix_private.check_cash(p_cash_amount, p_cash_payer);
    v_photos text[] := swapfix_private.clean_photo_paths(p_photo_paths, v_user, 6);
    v_exchange public.exchange_listings;
    v_offer uuid;
    v_conversation uuid;
begin
    perform swapfix_private.check_condition(p_condition);
    select * into v_exchange from public.exchange_listings where id = p_exchange_id for update;
    if not found or v_exchange.status = 'removed' then
        perform swapfix_private.fail('SF404', 'Exchange listing not found.');
    end if;
    if v_exchange.owner_id = v_user then
        perform swapfix_private.fail('SF403', 'You cannot send an offer to your own listing.');
    end if;
    if v_exchange.status <> 'open' then
        perform swapfix_private.fail('SF409', 'This exchange is no longer taking offers.');
    end if;
    if exists (
        select 1 from public.trade_offers
        where exchange_id = p_exchange_id and offerer_id = v_user and status in ('pending', 'accepted')
    ) then
        perform swapfix_private.fail('SF409', 'You already have an active offer on this listing.');
    end if;
    insert into public.trade_offers (exchange_id, offerer_id, owner_id, awaiting_user_id)
    values (p_exchange_id, v_user, v_exchange.owner_id, v_exchange.owner_id)
    returning id into v_offer;
    insert into public.trade_offer_terms (
        offer_id, version, proposed_by, device_title, brand, model, condition, known_defects, message,
        cash_amount, cash_payer, photo_owner_id, photo_paths
    ) values (
        v_offer, 1, v_user, v_title, v_brand, v_model, p_condition, v_defects, v_message,
        v_cash, p_cash_payer, v_user, v_photos
    );
    insert into public.trade_offer_events (offer_id, actor_id, event, version) values (v_offer, v_user, 'offered', 1);
    v_conversation := swapfix_private.ensure_conversation(
        'offer', v_offer, v_user, v_exchange.owner_id, 'Offer: ' || v_exchange.title
    );
    perform swapfix_private.post_message(v_conversation, v_user, v_message, false);
    perform swapfix_private.notify(
        v_exchange.owner_id, 'trade_offer', 'New trade offer', v_title || ' for ' || v_exchange.title,
        '/offers/' || v_offer, 'offer', v_offer
    );
    return jsonb_build_object('id', v_offer, 'conversation_id', v_conversation);
end;
$$;

-- Loads and locks an offer that the caller must answer, rejecting stale or conflicting decisions.
create function swapfix_private.lock_offer_for_response(
    p_offer_id uuid, p_user uuid, p_expected_version integer,
    out r_offer public.trade_offers, out r_exchange public.exchange_listings
)
language plpgsql set search_path = '' as $$
declare
    v_exchange_id uuid;
begin
    select exchange_id into v_exchange_id from public.trade_offers
    where id = p_offer_id and p_user in (offerer_id, owner_id);
    if v_exchange_id is null then
        perform swapfix_private.fail('SF404', 'Offer not found.');
    end if;
    select * into r_exchange from public.exchange_listings where id = v_exchange_id for update;
    select * into r_offer from public.trade_offers where id = p_offer_id for update;
    if r_offer.status <> 'pending' then
        perform swapfix_private.fail('SF409', 'This offer has already been decided.');
    end if;
    if p_expected_version is null or p_expected_version < 1 or r_offer.current_version is distinct from p_expected_version then
        perform swapfix_private.fail('SF409', 'These terms changed. Review the latest version first.');
    end if;
    if r_offer.awaiting_user_id <> p_user then
        perform swapfix_private.fail('SF403', 'It is the other party''s turn to respond.');
    end if;
    if r_exchange.status <> 'open' then
        perform swapfix_private.fail('SF409', 'This exchange is not open for decisions.');
    end if;
end;
$$;

create function swapfix_private.api_counter_offer(
    p_offer_id uuid, p_expected_version integer, p_device_title text, p_brand text, p_model text,
    p_condition text, p_known_defects text, p_message text, p_cash_amount numeric, p_cash_payer text,
    p_photo_paths text[] default null
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_profile();
    v_title text := swapfix_private.clean_text(p_device_title, 'Gadget name', 3, 150);
    v_brand text := swapfix_private.clean_text(p_brand, 'Brand', 1, 60);
    v_model text := swapfix_private.clean_text(p_model, 'Model', 0, 80);
    v_defects text := swapfix_private.clean_text(p_known_defects, 'Known defects', 0, 2000);
    v_message text := swapfix_private.clean_text(p_message, 'Message', 1, 2000);
    v_cash numeric := swapfix_private.check_cash(p_cash_amount, p_cash_payer);
    v_locked record;
    v_offer public.trade_offers;
    v_exchange public.exchange_listings;
    v_previous public.trade_offer_terms;
    v_photos text[];
    v_next integer;
    v_other uuid;
begin
    perform swapfix_private.check_condition(p_condition);
    select * into v_locked from swapfix_private.lock_offer_for_response(p_offer_id, v_user, p_expected_version);
    v_offer := v_locked.r_offer;
    v_exchange := v_locked.r_exchange;
    select * into v_previous from public.trade_offer_terms
    where offer_id = p_offer_id and version = v_offer.current_version;
    -- Photos show the offerer's gadget, so only the offerer can replace them.
    if p_photo_paths is not null and v_user = v_offer.offerer_id then
        v_photos := swapfix_private.clean_photo_paths(p_photo_paths, v_offer.offerer_id, 6);
    else
        v_photos := v_previous.photo_paths;
    end if;
    v_next := v_offer.current_version + 1;
    v_other := case when v_user = v_offer.owner_id then v_offer.offerer_id else v_offer.owner_id end;
    insert into public.trade_offer_terms (
        offer_id, version, proposed_by, device_title, brand, model, condition, known_defects, message,
        cash_amount, cash_payer, photo_owner_id, photo_paths
    ) values (
        p_offer_id, v_next, v_user, v_title, v_brand, v_model, p_condition, v_defects, v_message,
        v_cash, p_cash_payer, v_offer.offerer_id, v_photos
    );
    update public.trade_offers set current_version = v_next, awaiting_user_id = v_other where id = p_offer_id;
    insert into public.trade_offer_events (offer_id, actor_id, event, version) values (p_offer_id, v_user, 'countered', v_next);
    perform swapfix_private.notify(
        v_other, 'trade_counter', 'New counteroffer', v_exchange.title || ': your response is needed',
        '/offers/' || p_offer_id, 'offer', p_offer_id
    );
    return jsonb_build_object('id', p_offer_id, 'version', v_next, 'awaiting_user_id', v_other);
end;
$$;

create function swapfix_private.api_accept_offer(p_offer_id uuid, p_expected_version integer) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_profile();
    v_locked record;
    v_offer public.trade_offers;
    v_exchange public.exchange_listings;
    v_other uuid;
begin
    select * into v_locked from swapfix_private.lock_offer_for_response(p_offer_id, v_user, p_expected_version);
    v_offer := v_locked.r_offer;
    v_exchange := v_locked.r_exchange;
    update public.trade_offers
    set status = 'accepted', accepted_version = current_version, awaiting_user_id = null, decided_at = now()
    where id = p_offer_id;
    update public.exchange_listings set status = 'agreed', accepted_offer_id = p_offer_id where id = v_exchange.id;
    insert into public.trade_offer_events (offer_id, actor_id, event, version)
    values (p_offer_id, v_user, 'accepted', v_offer.current_version);
    v_other := case when v_user = v_offer.owner_id then v_offer.offerer_id else v_offer.owner_id end;
    perform swapfix_private.notify(
        v_other, 'trade_accepted', 'Trade offer accepted', v_exchange.title || ': arrange the handover in chat',
        '/offers/' || p_offer_id, 'offer', p_offer_id
    );
    return jsonb_build_object('id', p_offer_id, 'status', 'accepted', 'exchange_status', 'agreed');
end;
$$;

create function swapfix_private.api_decline_offer(p_offer_id uuid, p_expected_version integer, p_note text default '') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_profile();
    v_note text := swapfix_private.clean_text(p_note, 'Note', 0, 1000);
    v_locked record;
    v_offer public.trade_offers;
    v_other uuid;
begin
    select * into v_locked from swapfix_private.lock_offer_for_response(p_offer_id, v_user, p_expected_version);
    v_offer := v_locked.r_offer;
    update public.trade_offers set status = 'declined', awaiting_user_id = null, decided_at = now() where id = p_offer_id;
    insert into public.trade_offer_events (offer_id, actor_id, event, version, note)
    values (p_offer_id, v_user, 'declined', v_offer.current_version, v_note);
    v_other := case when v_user = v_offer.owner_id then v_offer.offerer_id else v_offer.owner_id end;
    perform swapfix_private.notify(
        v_other, 'trade_declined', 'Trade offer declined', (v_locked.r_exchange).title,
        '/offers/' || p_offer_id, 'offer', p_offer_id
    );
    return jsonb_build_object('id', p_offer_id, 'status', 'declined');
end;
$$;

create function swapfix_private.api_withdraw_offer(p_offer_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_profile();
    v_offer public.trade_offers;
    v_title text;
begin
    select * into v_offer from public.trade_offers where id = p_offer_id and offerer_id = v_user for update;
    if not found then
        perform swapfix_private.fail('SF404', 'Offer not found.');
    end if;
    if v_offer.status <> 'pending' then
        perform swapfix_private.fail('SF409', 'Only pending offers can be withdrawn.');
    end if;
    update public.trade_offers set status = 'withdrawn', awaiting_user_id = null, decided_at = now() where id = p_offer_id;
    insert into public.trade_offer_events (offer_id, actor_id, event, version)
    values (p_offer_id, v_user, 'withdrawn', v_offer.current_version);
    select title into v_title from public.exchange_listings where id = v_offer.exchange_id;
    perform swapfix_private.notify(
        v_offer.owner_id, 'trade_update', 'Offer withdrawn', v_title, '/offers/' || p_offer_id, 'offer', p_offer_id
    );
    return jsonb_build_object('id', p_offer_id, 'status', 'withdrawn');
end;
$$;

create function swapfix_private.api_cancel_agreement(p_exchange_id uuid, p_note text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_profile();
    v_note text := swapfix_private.clean_text(p_note, 'Reason', 2, 1000);
    v_exchange public.exchange_listings;
    v_offer public.trade_offers;
    v_other uuid;
begin
    select * into v_exchange from public.exchange_listings where id = p_exchange_id for update;
    if not found then
        perform swapfix_private.fail('SF404', 'Exchange listing not found.');
    end if;
    if v_exchange.status <> 'agreed' then
        perform swapfix_private.fail('SF409', 'This exchange has no active agreement.');
    end if;
    select * into v_offer from public.trade_offers where id = v_exchange.accepted_offer_id for update;
    if v_user not in (v_offer.owner_id, v_offer.offerer_id) then
        perform swapfix_private.fail('SF404', 'Exchange listing not found.');
    end if;
    update public.exchange_listings set status = 'open', accepted_offer_id = null where id = p_exchange_id;
    update public.trade_offers set status = 'cancelled', accepted_version = null, decided_at = now() where id = v_offer.id;
    insert into public.trade_offer_events (offer_id, actor_id, event, version, note)
    values (v_offer.id, v_user, 'cancelled', v_offer.current_version, v_note);
    v_other := case when v_user = v_offer.owner_id then v_offer.offerer_id else v_offer.owner_id end;
    perform swapfix_private.notify(
        v_other, 'trade_update', 'Exchange agreement cancelled', v_exchange.title || ': ' || v_note,
        '/offers/' || v_offer.id, 'offer', v_offer.id
    );
    return jsonb_build_object('id', p_exchange_id, 'status', 'open');
end;
$$;

create function swapfix_private.api_complete_exchange(p_exchange_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_profile();
    v_exchange public.exchange_listings;
    v_offer public.trade_offers;
begin
    select * into v_exchange from public.exchange_listings where id = p_exchange_id for update;
    if not found or v_exchange.owner_id <> v_user then
        perform swapfix_private.fail('SF404', 'Exchange listing not found.');
    end if;
    if v_exchange.status <> 'agreed' then
        perform swapfix_private.fail('SF409', 'Accept an offer before completing the exchange.');
    end if;
    select * into v_offer from public.trade_offers where id = v_exchange.accepted_offer_id for update;
    update public.trade_offers set status = 'completed', decided_at = now() where id = v_offer.id;
    update public.exchange_listings set status = 'completed', completed_at = now() where id = p_exchange_id;
    insert into public.trade_offer_events (offer_id, actor_id, event, version)
    values (v_offer.id, v_user, 'completed', v_offer.current_version);
    perform swapfix_private.close_pending_offers(v_exchange, v_user, 'The exchange was completed with another offer.');
    perform swapfix_private.notify(
        v_offer.offerer_id, 'trade_update', 'Exchange completed', v_exchange.title,
        '/offers/' || v_offer.id, 'offer', v_offer.id
    );
    return jsonb_build_object('id', p_exchange_id, 'status', 'completed');
end;
$$;

create function public.sf_search_exchanges(
    p_query text default null, p_category text default null, p_brand text default null,
    p_condition text default null, p_location text default null, p_limit integer default 24, p_offset integer default 0
) returns jsonb
language sql stable security invoker set search_path = '' as $$
    with filtered as (
        select e.* from public.exchange_listings e
        where e.status in ('open', 'agreed')
          and (nullif(btrim(p_query), '') is null or e.search @@ swapfix_private.prefix_tsquery(p_query))
          and (nullif(p_category, '') is null or e.category = p_category)
          and (nullif(btrim(p_brand), '') is null or lower(e.brand) = lower(btrim(p_brand)))
          and (nullif(p_condition, '') is null or e.condition = p_condition)
          and (nullif(btrim(p_location), '') is null or e.location ilike swapfix_private.like_pattern(p_location))
    ), page as (
        select f.*, row_number() over (order by (f.status = 'open') desc, f.created_at desc, f.id) as position
        from filtered f
        order by position
        limit least(greatest(coalesce(p_limit, 24), 1), 48)
        offset least(greatest(coalesce(p_offset, 0), 0), 10000)
    )
    select jsonb_build_object(
        'total', (select count(*) from filtered),
        'items', coalesce((
            select jsonb_agg(jsonb_build_object(
                'id', p.id, 'title', p.title, 'category', p.category, 'brand', p.brand, 'model', p.model,
                'condition', p.condition, 'known_defects', p.known_defects, 'location', p.location,
                'photo_paths', p.photo_paths, 'wanted_item', p.wanted_item, 'cash_preference', p.cash_preference,
                'status', p.status, 'created_at', p.created_at,
                'owner', jsonb_build_object('id', o.id, 'display_name', o.display_name, 'avatar_path', o.avatar_path)
            ) order by p.position)
            from page p join public.profiles o on o.id = p.owner_id
        ), '[]'::jsonb)
    );
$$;


-- SOURCE: 20261119090400_repair.sql
-- SwapFix 4/8: repair services, requests, quotations, added costs and history.
--
-- Main flow: request_sent -> quotation_sent -> accepted -> in_repair -> ready_for_pickup -> completed.
-- Decisions the README left open:
--   * Declining a quotation returns the job to request_sent. The declined quotation is kept and
--     the technician may send a new version, or either party may cancel.
--   * A technician may replace a still-pending quotation; the old version becomes superseded.
--   * After acceptance the quotation is frozen. Price changes happen only through added costs.
--   * The customer may cancel before work starts. The technician may cancel until the device
--     is ready for pickup, with a reason. Cancelled jobs keep their full history.
--   * A pending added cost blocks moving to ready_for_pickup. A declined one leaves the total alone.

create table public.repair_services (
    id uuid primary key default gen_random_uuid(),
    technician_id uuid not null references public.technician_profiles (user_id),
    name text not null check (char_length(name) between 3 and 120),
    description text not null default '' check (char_length(description) <= 2000),
    supported_brands text[] not null default '{}',
    supported_models text[] not null default '{}',
    estimated_price numeric(12, 2) not null check (estimated_price >= 0),
    is_active boolean not null default true,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);
create index repair_services_technician_idx on public.repair_services (technician_id, is_active, created_at desc);
create index repair_services_active_idx on public.repair_services (created_at desc) where is_active;
create trigger repair_services_touch before update on public.repair_services
for each row execute function swapfix_private.touch_updated_at();

create table public.repair_requests (
    id uuid primary key default gen_random_uuid(),
    customer_id uuid not null references public.profiles (id),
    technician_id uuid not null references public.technician_profiles (user_id),
    service_id uuid references public.repair_services (id),
    requested_service text not null default '' check (char_length(requested_service) <= 120),
    device_type text not null check (device_type in ('cellphone', 'tablet', 'laptop', 'other')),
    device_brand text not null check (char_length(device_brand) between 1 and 60),
    device_model text not null check (char_length(device_model) between 1 and 80),
    problem text not null check (char_length(problem) between 5 and 4000),
    photo_paths text[] not null default '{}',
    status text not null default 'request_sent' check (status in (
        'request_sent', 'quotation_sent', 'accepted', 'in_repair', 'ready_for_pickup', 'completed', 'cancelled'
    )),
    accepted_quotation_id uuid,
    approved_total numeric(12, 2) check (approved_total >= 0),
    estimated_completion date,
    status_changed_at timestamptz not null default now(),
    completed_at timestamptz,
    cancelled_at timestamptz,
    cancelled_by uuid references public.profiles (id),
    cancel_reason text not null default '' check (char_length(cancel_reason) <= 1000),
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint repair_not_self check (customer_id <> technician_id),
    constraint repair_photos_owned check (swapfix_private.valid_photo_paths(photo_paths, customer_id, 6)),
    constraint repair_work_requires_approval check (
        status not in ('accepted', 'in_repair', 'ready_for_pickup', 'completed')
        or (accepted_quotation_id is not null and approved_total is not null)
    ),
    constraint repair_completed_time check ((status = 'completed') = (completed_at is not null)),
    constraint repair_cancelled_time check ((status = 'cancelled') = (cancelled_at is not null))
);
create index repair_requests_customer_idx on public.repair_requests (customer_id, created_at desc);
create index repair_requests_technician_idx on public.repair_requests (technician_id, status, updated_at desc);
create index repair_requests_service_idx on public.repair_requests (service_id);
create index repair_requests_quotation_idx on public.repair_requests (accepted_quotation_id);
create index repair_requests_cancelled_by_idx on public.repair_requests (cancelled_by);
create index repair_requests_photos_idx on public.repair_requests using gin (photo_paths);
create trigger repair_requests_touch before update on public.repair_requests
for each row execute function swapfix_private.touch_updated_at();

create table public.repair_quotations (
    id uuid primary key default gen_random_uuid(),
    repair_id uuid not null references public.repair_requests (id) on delete cascade,
    technician_id uuid not null references public.profiles (id),
    version integer not null check (version >= 1),
    scope text not null check (char_length(scope) between 5 and 4000),
    parts text not null default '' check (char_length(parts) <= 2000),
    cost numeric(12, 2) not null check (cost > 0),
    estimated_completion date not null,
    status text not null default 'pending' check (status in ('pending', 'accepted', 'declined', 'superseded', 'withdrawn')),
    decision_note text not null default '' check (char_length(decision_note) <= 1000),
    decided_at timestamptz,
    created_at timestamptz not null default now(),
    unique (repair_id, version)
);
create unique index repair_quotations_one_pending_idx on public.repair_quotations (repair_id) where status = 'pending';
create unique index repair_quotations_one_accepted_idx on public.repair_quotations (repair_id) where status = 'accepted';
create index repair_quotations_technician_idx on public.repair_quotations (technician_id);

alter table public.repair_requests
    add constraint repair_requests_accepted_quotation_fkey
    foreign key (accepted_quotation_id) references public.repair_quotations (id);

create table public.repair_added_costs (
    id uuid primary key default gen_random_uuid(),
    repair_id uuid not null references public.repair_requests (id) on delete cascade,
    technician_id uuid not null references public.profiles (id),
    reason text not null check (char_length(reason) between 5 and 2000),
    proposed_work text not null check (char_length(proposed_work) between 5 and 2000),
    amount numeric(12, 2) not null check (amount > 0),
    previous_total numeric(12, 2) not null check (previous_total >= 0),
    revised_total numeric(12, 2) not null,
    previous_completion date,
    revised_completion date,
    status text not null default 'pending' check (status in ('pending', 'accepted', 'declined', 'withdrawn')),
    decision_note text not null default '' check (char_length(decision_note) <= 1000),
    decided_at timestamptz,
    created_at timestamptz not null default now(),
    constraint repair_added_cost_total check (revised_total = previous_total + amount)
);
create unique index repair_added_costs_one_pending_idx on public.repair_added_costs (repair_id) where status = 'pending';
create index repair_added_costs_repair_idx on public.repair_added_costs (repair_id, created_at);
create index repair_added_costs_technician_idx on public.repair_added_costs (technician_id);

create table public.repair_events (
    id uuid primary key default gen_random_uuid(),
    repair_id uuid not null references public.repair_requests (id) on delete cascade,
    actor_id uuid references public.profiles (id),
    kind text not null check (kind in (
        'status', 'quotation_sent', 'quotation_accepted', 'quotation_declined', 'quotation_superseded',
        'added_cost_requested', 'added_cost_accepted', 'added_cost_declined', 'added_cost_withdrawn', 'review_submitted'
    )),
    from_status text,
    to_status text,
    amount numeric(12, 2),
    related_id uuid,
    note text not null default '' check (char_length(note) <= 1000),
    created_at timestamptz not null default now()
);
create index repair_events_repair_idx on public.repair_events (repair_id, created_at);
create index repair_events_actor_idx on public.repair_events (actor_id);
create trigger repair_events_immutable before update on public.repair_events
for each row execute function swapfix_private.forbid_update();

-- Guards apply to every writer, including database administrators and future functions.
create function swapfix_private.guard_repair_status() returns trigger
language plpgsql set search_path = '' as $$
begin
    if tg_op = 'INSERT' then
        if new.status <> 'request_sent' then
            raise exception using errcode = 'SF409', message = 'New repairs must start as Request Sent.';
        end if;
        return new;
    end if;
    if new.status = old.status then
        return new;
    end if;
    if not ((old.status, new.status) in (
        ('request_sent', 'quotation_sent'), ('request_sent', 'cancelled'),
        ('quotation_sent', 'accepted'), ('quotation_sent', 'request_sent'), ('quotation_sent', 'cancelled'),
        ('accepted', 'in_repair'), ('accepted', 'cancelled'),
        ('in_repair', 'ready_for_pickup'), ('in_repair', 'cancelled'),
        ('ready_for_pickup', 'completed')
    )) then
        raise exception using errcode = 'SF409', message = 'That repair status change is not allowed.';
    end if;
    new.status_changed_at := now();
    if new.status = 'completed' then
        new.completed_at := now();
    end if;
    return new;
end;
$$;
create trigger repair_requests_guard_status before insert or update of status on public.repair_requests
for each row execute function swapfix_private.guard_repair_status();

create function swapfix_private.record_repair_status() returns trigger
language plpgsql set search_path = '' as $$
begin
    if tg_op = 'UPDATE' and new.status = old.status then
        return null;
    end if;
    insert into public.repair_events (repair_id, actor_id, kind, from_status, to_status, note)
    values (
        new.id, auth.uid(), 'status', case when tg_op = 'UPDATE' then old.status end, new.status,
        coalesce(current_setting('swapfix.status_note', true), '')
    );
    return null;
end;
$$;
create trigger repair_requests_record_status after insert or update of status on public.repair_requests
for each row execute function swapfix_private.record_repair_status();

create function swapfix_private.guard_quotation_terms() returns trigger
language plpgsql set search_path = '' as $$
begin
    if (new.repair_id, new.technician_id, new.version, new.scope, new.parts, new.cost, new.estimated_completion, new.created_at)
       is distinct from
       (old.repair_id, old.technician_id, old.version, old.scope, old.parts, old.cost, old.estimated_completion, old.created_at)
    then
        raise exception using errcode = 'SF409', message = 'Quotation terms cannot be changed. Send a new version.';
    end if;
    if old.status <> 'pending' then
        raise exception using errcode = 'SF409', message = 'This quotation has already been decided.';
    end if;
    return new;
end;
$$;
create trigger repair_quotations_guard before update on public.repair_quotations
for each row execute function swapfix_private.guard_quotation_terms();

create function swapfix_private.guard_added_cost_terms() returns trigger
language plpgsql set search_path = '' as $$
begin
    if (new.repair_id, new.technician_id, new.reason, new.proposed_work, new.amount, new.previous_total,
        new.revised_total, new.previous_completion, new.revised_completion, new.created_at)
       is distinct from
       (old.repair_id, old.technician_id, old.reason, old.proposed_work, old.amount, old.previous_total,
        old.revised_total, old.previous_completion, old.revised_completion, old.created_at)
    then
        raise exception using errcode = 'SF409', message = 'Added-cost terms cannot be changed.';
    end if;
    if old.status <> 'pending' then
        raise exception using errcode = 'SF409', message = 'This added cost has already been decided.';
    end if;
    return new;
end;
$$;
create trigger repair_added_costs_guard before update on public.repair_added_costs
for each row execute function swapfix_private.guard_added_cost_terms();

create function swapfix_private.add_repair_event(
    p_repair uuid, p_actor uuid, p_kind text, p_related uuid, p_amount numeric, p_note text
) returns void
language sql set search_path = '' as $$
    insert into public.repair_events (repair_id, actor_id, kind, related_id, amount, note)
    values (p_repair, p_actor, p_kind, p_related, p_amount, coalesce(p_note, ''));
$$;

create function swapfix_private.status_label(p_status text) returns text
language sql immutable set search_path = '' as $$
    select case p_status
        when 'request_sent' then 'Request Sent' when 'quotation_sent' then 'Quotation Sent'
        when 'accepted' then 'Accepted' when 'in_repair' then 'In Repair'
        when 'ready_for_pickup' then 'Ready for Pickup' when 'completed' then 'Completed'
        when 'cancelled' then 'Cancelled' else p_status end;
$$;

create function swapfix_private.future_date(p_value date, p_label text) returns date
language plpgsql set search_path = '' as $$
begin
    if p_value is null or p_value < current_date or p_value > current_date + 730 then
        perform swapfix_private.fail('SF422', p_label || ' must be a date from today up to two years ahead.');
    end if;
    return p_value;
end;
$$;

-- Services
create function swapfix_private.api_save_repair_service(
    p_id uuid, p_name text, p_description text, p_supported_brands text[], p_supported_models text[], p_estimated_price numeric
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_technician();
    v_name text := swapfix_private.clean_text(p_name, 'Service name', 3, 120);
    v_description text := swapfix_private.clean_text(p_description, 'Description', 0, 2000);
    v_brands text[] := swapfix_private.clean_list(p_supported_brands, 'Brands', 30, 60);
    v_models text[] := swapfix_private.clean_list(p_supported_models, 'Models', 60, 80);
    v_price numeric := swapfix_private.clean_money(p_estimated_price, 'Estimated price', 0);
    v_id uuid;
begin
    if p_id is null then
        insert into public.repair_services (technician_id, name, description, supported_brands, supported_models, estimated_price)
        values (v_user, v_name, v_description, v_brands, v_models, v_price)
        returning id into v_id;
    else
        update public.repair_services set
            name = v_name, description = v_description, supported_brands = v_brands,
            supported_models = v_models, estimated_price = v_price
        where id = p_id and technician_id = v_user
        returning id into v_id;
        if v_id is null then
            perform swapfix_private.fail('SF404', 'Service not found.');
        end if;
    end if;
    return jsonb_build_object('id', v_id);
end;
$$;

create function swapfix_private.api_set_service_active(p_id uuid, p_active boolean) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_technician();
begin
    update public.repair_services set is_active = coalesce(p_active, false) where id = p_id and technician_id = v_user;
    if not found then
        perform swapfix_private.fail('SF404', 'Service not found.');
    end if;
    return jsonb_build_object('id', p_id, 'is_active', coalesce(p_active, false));
end;
$$;

-- Requests
create function swapfix_private.api_create_repair_request(
    p_technician_id uuid, p_service_id uuid, p_device_type text, p_device_brand text, p_device_model text,
    p_problem text, p_photo_paths text[]
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_profile();
    v_brand text := swapfix_private.clean_text(p_device_brand, 'Device brand', 1, 60);
    v_model text := swapfix_private.clean_text(p_device_model, 'Device model', 1, 80);
    v_problem text := swapfix_private.clean_text(p_problem, 'Problem description', 5, 4000);
    v_photos text[] := swapfix_private.clean_photo_paths(p_photo_paths, v_user, 6);
    v_service public.repair_services;
    v_customer text;
    v_id uuid;
    v_conversation uuid;
begin
    if p_device_type is null or p_device_type not in ('cellphone', 'tablet', 'laptop', 'other') then
        perform swapfix_private.fail('SF422', 'Choose a device type.');
    end if;
    if p_technician_id = v_user then
        perform swapfix_private.fail('SF403', 'You cannot request a repair from yourself.');
    end if;
    if not exists (
        select 1 from public.technician_profiles t
        join public.profiles p on p.id = t.user_id and p.account_type = 'technician'
        where t.user_id = p_technician_id
    ) then
        perform swapfix_private.fail('SF404', 'Technician not found.');
    end if;
    if p_service_id is not null then
        select * into v_service from public.repair_services
        where id = p_service_id and technician_id = p_technician_id and is_active;
        if not found then
            perform swapfix_private.fail('SF422', 'That service is not available from this technician.');
        end if;
    end if;
    insert into public.repair_requests (
        customer_id, technician_id, service_id, requested_service, device_type, device_brand, device_model, problem, photo_paths
    ) values (
        v_user, p_technician_id, p_service_id, coalesce(v_service.name, ''), p_device_type, v_brand, v_model, v_problem, v_photos
    ) returning id into v_id;
    v_conversation := swapfix_private.ensure_conversation(
        'repair', v_id, v_user, p_technician_id, 'Repair: ' || v_brand || ' ' || v_model
    );
    select display_name into v_customer from public.profiles where id = v_user;
    perform swapfix_private.notify(
        p_technician_id, 'repair_request', 'New repair request', v_customer || ': ' || v_brand || ' ' || v_model,
        '/repairs/' || v_id, 'repair', v_id
    );
    return jsonb_build_object('id', v_id, 'conversation_id', v_conversation);
end;
$$;

create function swapfix_private.lock_repair_as_technician(p_repair_id uuid, p_user uuid) returns public.repair_requests
language plpgsql set search_path = '' as $$
declare
    v_repair public.repair_requests;
begin
    select * into v_repair from public.repair_requests where id = p_repair_id for update;
    if not found or v_repair.technician_id <> p_user then
        perform swapfix_private.fail('SF404', 'Repair not found.');
    end if;
    return v_repair;
end;
$$;

create function swapfix_private.lock_repair_as_customer(p_repair_id uuid, p_user uuid) returns public.repair_requests
language plpgsql set search_path = '' as $$
declare
    v_repair public.repair_requests;
begin
    select * into v_repair from public.repair_requests where id = p_repair_id for update;
    if not found or v_repair.customer_id <> p_user then
        perform swapfix_private.fail('SF404', 'Repair not found.');
    end if;
    return v_repair;
end;
$$;

-- Quotations
create function swapfix_private.api_send_quotation(
    p_repair_id uuid, p_scope text, p_parts text, p_cost numeric, p_estimated_completion date
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_technician();
    v_scope text := swapfix_private.clean_text(p_scope, 'Repair details', 5, 4000);
    v_parts text := swapfix_private.clean_text(p_parts, 'Parts', 0, 2000);
    v_cost numeric := swapfix_private.clean_money(p_cost, 'Repair cost', 0.01);
    v_date date := swapfix_private.future_date(p_estimated_completion, 'Completion date');
    v_repair public.repair_requests := swapfix_private.lock_repair_as_technician(p_repair_id, v_user);
    v_version integer;
    v_superseded uuid;
    v_id uuid;
begin
    if v_repair.status not in ('request_sent', 'quotation_sent') then
        perform swapfix_private.fail('SF409', 'A quotation cannot be sent at this stage.');
    end if;
    update public.repair_quotations set status = 'superseded', decided_at = now()
    where repair_id = p_repair_id and status = 'pending'
    returning id into v_superseded;
    if v_superseded is not null then
        perform swapfix_private.add_repair_event(p_repair_id, v_user, 'quotation_superseded', v_superseded, null, '');
    end if;
    select coalesce(max(version), 0) + 1 into v_version from public.repair_quotations where repair_id = p_repair_id;
    insert into public.repair_quotations (repair_id, technician_id, version, scope, parts, cost, estimated_completion)
    values (p_repair_id, v_user, v_version, v_scope, v_parts, v_cost, v_date)
    returning id into v_id;
    if v_repair.status = 'request_sent' then
        update public.repair_requests set status = 'quotation_sent' where id = p_repair_id;
    end if;
    perform swapfix_private.add_repair_event(p_repair_id, v_user, 'quotation_sent', v_id, v_cost, '');
    perform swapfix_private.notify(
        v_repair.customer_id, 'quotation_sent', 'Repair quotation received',
        v_repair.device_brand || ' ' || v_repair.device_model, '/repairs/' || p_repair_id, 'repair', p_repair_id
    );
    return jsonb_build_object('id', v_id, 'version', v_version);
end;
$$;

create function swapfix_private.api_decide_quotation(p_quotation_id uuid, p_decision text, p_note text default '') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_profile();
    v_note text := swapfix_private.clean_text(p_note, 'Note', 0, 1000);
    v_repair_id uuid;
    v_repair public.repair_requests;
    v_quotation public.repair_quotations;
begin
    if p_decision is null or p_decision not in ('accepted', 'declined') then
        perform swapfix_private.fail('SF422', 'Choose accept or decline.');
    end if;
    select repair_id into v_repair_id from public.repair_quotations where id = p_quotation_id;
    if v_repair_id is null then
        perform swapfix_private.fail('SF404', 'Quotation not found.');
    end if;
    v_repair := swapfix_private.lock_repair_as_customer(v_repair_id, v_user);
    select * into v_quotation from public.repair_quotations where id = p_quotation_id for update;
    if v_quotation.status <> 'pending' or v_repair.status <> 'quotation_sent' then
        perform swapfix_private.fail('SF409', 'This quotation is no longer open. Review the latest version.');
    end if;
    update public.repair_quotations
    set status = p_decision, decision_note = v_note, decided_at = now()
    where id = p_quotation_id;
    perform set_config('swapfix.status_note', v_note, true);
    if p_decision = 'accepted' then
        update public.repair_requests set
            status = 'accepted', accepted_quotation_id = p_quotation_id,
            approved_total = v_quotation.cost, estimated_completion = v_quotation.estimated_completion
        where id = v_repair_id;
    else
        update public.repair_requests set status = 'request_sent' where id = v_repair_id;
    end if;
    perform set_config('swapfix.status_note', '', true);
    perform swapfix_private.add_repair_event(
        v_repair_id, v_user, 'quotation_' || p_decision, p_quotation_id, v_quotation.cost, v_note
    );
    perform swapfix_private.notify(
        v_repair.technician_id,
        case p_decision when 'accepted' then 'quotation_accepted' else 'quotation_declined' end,
        case p_decision when 'accepted' then 'Quotation accepted' else 'Quotation declined' end,
        v_repair.device_brand || ' ' || v_repair.device_model, '/repairs/' || v_repair_id, 'repair', v_repair_id
    );
    return jsonb_build_object('id', p_quotation_id, 'status', p_decision);
end;
$$;

-- Added costs
create function swapfix_private.api_request_added_cost(
    p_repair_id uuid, p_reason text, p_proposed_work text, p_amount numeric, p_revised_completion date default null
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_technician();
    v_reason text := swapfix_private.clean_text(p_reason, 'Reason', 5, 2000);
    v_work text := swapfix_private.clean_text(p_proposed_work, 'Proposed work', 5, 2000);
    v_amount numeric := swapfix_private.clean_money(p_amount, 'Added amount', 0.01);
    v_repair public.repair_requests := swapfix_private.lock_repair_as_technician(p_repair_id, v_user);
    v_id uuid;
begin
    if p_revised_completion is not null then
        perform swapfix_private.future_date(p_revised_completion, 'Revised completion date');
    end if;
    if v_repair.status not in ('accepted', 'in_repair') then
        perform swapfix_private.fail('SF409', 'Added costs can be requested only on an accepted or active repair.');
    end if;
    if exists (select 1 from public.repair_added_costs where repair_id = p_repair_id and status = 'pending') then
        perform swapfix_private.fail('SF409', 'An added cost is already waiting for the customer.');
    end if;
    if v_repair.approved_total + v_amount >= 10000000000 then
        perform swapfix_private.fail('SF422', 'The revised total is too large.');
    end if;
    insert into public.repair_added_costs (
        repair_id, technician_id, reason, proposed_work, amount, previous_total, revised_total,
        previous_completion, revised_completion
    ) values (
        p_repair_id, v_user, v_reason, v_work, v_amount, v_repair.approved_total, v_repair.approved_total + v_amount,
        v_repair.estimated_completion, p_revised_completion
    ) returning id into v_id;
    perform swapfix_private.add_repair_event(p_repair_id, v_user, 'added_cost_requested', v_id, v_amount, left(v_reason, 1000));
    perform swapfix_private.notify(
        v_repair.customer_id, 'added_cost_requested', 'Added cost needs approval',
        v_repair.device_brand || ' ' || v_repair.device_model, '/repairs/' || p_repair_id, 'repair', p_repair_id
    );
    return jsonb_build_object('id', v_id, 'revised_total', v_repair.approved_total + v_amount);
end;
$$;

create function swapfix_private.api_withdraw_added_cost(p_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_technician();
    v_repair_id uuid;
    v_repair public.repair_requests;
    v_cost public.repair_added_costs;
begin
    select repair_id into v_repair_id from public.repair_added_costs where id = p_id;
    if v_repair_id is null then
        perform swapfix_private.fail('SF404', 'Added cost not found.');
    end if;
    v_repair := swapfix_private.lock_repair_as_technician(v_repair_id, v_user);
    select * into v_cost from public.repair_added_costs where id = p_id for update;
    if v_cost.status <> 'pending' then
        perform swapfix_private.fail('SF409', 'This added cost has already been decided.');
    end if;
    update public.repair_added_costs set status = 'withdrawn', decided_at = now() where id = p_id;
    perform swapfix_private.add_repair_event(v_repair_id, v_user, 'added_cost_withdrawn', p_id, v_cost.amount, '');
    perform swapfix_private.notify(
        v_repair.customer_id, 'repair_status', 'Added cost withdrawn',
        v_repair.device_brand || ' ' || v_repair.device_model, '/repairs/' || v_repair_id, 'repair', v_repair_id
    );
    return jsonb_build_object('id', p_id, 'status', 'withdrawn');
end;
$$;

create function swapfix_private.api_decide_added_cost(p_id uuid, p_decision text, p_note text default '') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_profile();
    v_note text := swapfix_private.clean_text(p_note, 'Note', 0, 1000);
    v_repair_id uuid;
    v_repair public.repair_requests;
    v_cost public.repair_added_costs;
begin
    if p_decision is null or p_decision not in ('accepted', 'declined') then
        perform swapfix_private.fail('SF422', 'Choose accept or decline.');
    end if;
    select repair_id into v_repair_id from public.repair_added_costs where id = p_id;
    if v_repair_id is null then
        perform swapfix_private.fail('SF404', 'Added cost not found.');
    end if;
    v_repair := swapfix_private.lock_repair_as_customer(v_repair_id, v_user);
    select * into v_cost from public.repair_added_costs where id = p_id for update;
    if v_cost.status <> 'pending' then
        perform swapfix_private.fail('SF409', 'This added cost has already been decided.');
    end if;
    if v_repair.status not in ('accepted', 'in_repair') or v_repair.approved_total <> v_cost.previous_total then
        perform swapfix_private.fail('SF409', 'This repair changed. Refresh and try again.');
    end if;
    update public.repair_added_costs set status = p_decision, decision_note = v_note, decided_at = now() where id = p_id;
    if p_decision = 'accepted' then
        update public.repair_requests set
            approved_total = v_cost.revised_total,
            estimated_completion = coalesce(v_cost.revised_completion, estimated_completion)
        where id = v_repair_id;
    end if;
    perform swapfix_private.add_repair_event(v_repair_id, v_user, 'added_cost_' || p_decision, p_id, v_cost.amount, v_note);
    perform swapfix_private.notify(
        v_repair.technician_id,
        case p_decision when 'accepted' then 'added_cost_accepted' else 'added_cost_declined' end,
        case p_decision when 'accepted' then 'Added cost approved' else 'Added cost declined' end,
        v_repair.device_brand || ' ' || v_repair.device_model, '/repairs/' || v_repair_id, 'repair', v_repair_id
    );
    return jsonb_build_object('id', p_id, 'status', p_decision);
end;
$$;

-- Progress
create function swapfix_private.api_update_repair_status(
    p_repair_id uuid, p_expected_status text, p_status text, p_note text default ''
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_technician();
    v_note text := swapfix_private.clean_text(p_note, 'Note', 0, 1000);
    v_repair public.repair_requests := swapfix_private.lock_repair_as_technician(p_repair_id, v_user);
begin
    if v_repair.status is distinct from p_expected_status then
        perform swapfix_private.fail('SF409', 'This repair changed. Refresh and try again.');
    end if;
    if not ((v_repair.status, p_status) in (
        ('accepted', 'in_repair'), ('in_repair', 'ready_for_pickup'), ('ready_for_pickup', 'completed')
    )) then
        perform swapfix_private.fail('SF409', 'That repair status change is not allowed.');
    end if;
    if p_status = 'ready_for_pickup' and exists (
        select 1 from public.repair_added_costs where repair_id = p_repair_id and status = 'pending'
    ) then
        perform swapfix_private.fail('SF409', 'Resolve the pending added cost first.');
    end if;
    perform set_config('swapfix.status_note', v_note, true);
    update public.repair_requests set status = p_status where id = p_repair_id;
    perform set_config('swapfix.status_note', '', true);
    perform swapfix_private.notify(
        v_repair.customer_id, 'repair_status', 'Repair: ' || swapfix_private.status_label(p_status),
        v_repair.device_brand || ' ' || v_repair.device_model, '/repairs/' || p_repair_id, 'repair', p_repair_id
    );
    return jsonb_build_object('id', p_repair_id, 'status', p_status);
end;
$$;

create function swapfix_private.api_cancel_repair(p_repair_id uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_profile();
    v_reason text := swapfix_private.clean_text(p_reason, 'Reason', 2, 1000);
    v_repair public.repair_requests;
    v_other uuid;
begin
    select * into v_repair from public.repair_requests where id = p_repair_id for update;
    if not found or v_user not in (v_repair.customer_id, v_repair.technician_id) then
        perform swapfix_private.fail('SF404', 'Repair not found.');
    end if;
    if v_user = v_repair.customer_id and v_repair.status not in ('request_sent', 'quotation_sent', 'accepted') then
        perform swapfix_private.fail('SF409', 'Work has started. Ask the technician to cancel this repair.');
    end if;
    if v_user = v_repair.technician_id and v_repair.status not in ('request_sent', 'quotation_sent', 'accepted', 'in_repair') then
        perform swapfix_private.fail('SF409', 'This repair can no longer be cancelled.');
    end if;
    update public.repair_quotations set status = 'withdrawn', decided_at = now()
    where repair_id = p_repair_id and status = 'pending';
    update public.repair_added_costs set status = 'withdrawn', decided_at = now()
    where repair_id = p_repair_id and status = 'pending';
    perform set_config('swapfix.status_note', v_reason, true);
    update public.repair_requests
    set status = 'cancelled', cancelled_at = now(), cancelled_by = v_user, cancel_reason = v_reason
    where id = p_repair_id;
    perform set_config('swapfix.status_note', '', true);
    v_other := case when v_user = v_repair.customer_id then v_repair.technician_id else v_repair.customer_id end;
    perform swapfix_private.notify(
        v_other, 'repair_status', 'Repair cancelled', v_repair.device_brand || ' ' || v_repair.device_model || ': ' || v_reason,
        '/repairs/' || p_repair_id, 'repair', p_repair_id
    );
    return jsonb_build_object('id', p_repair_id, 'status', 'cancelled');
end;
$$;

-- Technician discovery. SECURITY INVOKER: only public rows are visible.
create function public.sf_search_technicians(
    p_query text default null, p_area text default null, p_specialty text default null, p_brand text default null,
    p_limit integer default 24, p_offset integer default 0
) returns jsonb
language sql stable security invoker set search_path = '' as $$
    with filtered as (
        select t.*, p.display_name, p.avatar_path
        from public.technician_profiles t
        join public.profiles p on p.id = t.user_id and p.account_type = 'technician'
        where cardinality(t.specialties) > 0
          and (nullif(btrim(p_area), '') is null
               or t.location ilike swapfix_private.like_pattern(p_area)
               or t.service_area ilike swapfix_private.like_pattern(p_area))
          and (nullif(btrim(p_specialty), '') is null
               or exists (select 1 from unnest(t.specialties) s where s ilike swapfix_private.like_pattern(p_specialty))
               or exists (select 1 from public.repair_services r
                          where r.technician_id = t.user_id and r.is_active
                            and r.name ilike swapfix_private.like_pattern(p_specialty)))
          and (nullif(btrim(p_brand), '') is null
               or exists (select 1 from unnest(t.supported_brands) b where lower(b) = lower(btrim(p_brand)))
               or exists (select 1 from public.repair_services r, unnest(r.supported_brands) b
                          where r.technician_id = t.user_id and r.is_active and lower(b) = lower(btrim(p_brand))))
          and (nullif(btrim(p_query), '') is null
               or p.display_name ilike swapfix_private.like_pattern(p_query)
               or t.headline ilike swapfix_private.like_pattern(p_query)
               or exists (select 1 from unnest(t.specialties) s where s ilike swapfix_private.like_pattern(p_query)))
    ), page as (
        select f.*, row_number() over (order by f.rating_average desc, f.rating_count desc, f.created_at desc, f.user_id) as position
        from filtered f
        order by position
        limit least(greatest(coalesce(p_limit, 24), 1), 48)
        offset least(greatest(coalesce(p_offset, 0), 0), 10000)
    )
    select jsonb_build_object(
        'total', (select count(*) from filtered),
        'items', coalesce((
            select jsonb_agg(jsonb_build_object(
                'id', p.user_id, 'display_name', p.display_name, 'avatar_path', p.avatar_path, 'headline', p.headline,
                'location', p.location, 'service_area', p.service_area, 'available_hours', p.available_hours,
                'specialties', p.specialties, 'supported_brands', p.supported_brands,
                'rating_average', p.rating_average, 'rating_count', p.rating_count,
                'starting_price', (select min(r.estimated_price) from public.repair_services r
                                   where r.technician_id = p.user_id and r.is_active)
            ) order by p.position)
            from page p
        ), '[]'::jsonb)
    );
$$;


-- SOURCE: 20261119090500_messaging.sql
-- SwapFix 5/8: two-party, context-linked conversations and messages.

create table public.conversations (
    id uuid primary key default gen_random_uuid(),
    context_type text not null check (context_type in ('listing', 'offer', 'repair')),
    listing_id uuid references public.product_listings (id),
    offer_id uuid references public.trade_offers (id),
    repair_id uuid references public.repair_requests (id),
    initiator_id uuid not null references public.profiles (id),
    recipient_id uuid not null references public.profiles (id),
    context_title text not null check (char_length(context_title) between 1 and 200),
    initiator_unread integer not null default 0 check (initiator_unread >= 0),
    recipient_unread integer not null default 0 check (recipient_unread >= 0),
    last_message_preview text not null default '' check (char_length(last_message_preview) <= 160),
    last_message_at timestamptz,
    created_at timestamptz not null default now(),
    constraint conversations_not_self check (initiator_id <> recipient_id),
    constraint conversations_one_context check (
        (context_type = 'listing' and listing_id is not null and offer_id is null and repair_id is null)
        or (context_type = 'offer' and offer_id is not null and listing_id is null and repair_id is null)
        or (context_type = 'repair' and repair_id is not null and listing_id is null and offer_id is null)
    ),
    unique (listing_id, initiator_id),
    unique (offer_id),
    unique (repair_id)
);
create index conversations_initiator_idx on public.conversations (initiator_id, last_message_at desc nulls last);
create index conversations_recipient_idx on public.conversations (recipient_id, last_message_at desc nulls last);

create table public.messages (
    id uuid primary key default gen_random_uuid(),
    conversation_id uuid not null references public.conversations (id) on delete cascade,
    sender_id uuid not null references public.profiles (id),
    body text not null check (char_length(body) between 1 and 4000),
    created_at timestamptz not null default now()
);
create index messages_conversation_idx on public.messages (conversation_id, created_at desc);
create index messages_sender_idx on public.messages (sender_id);
create trigger messages_immutable before update on public.messages
for each row execute function swapfix_private.forbid_update();

create function swapfix_private.ensure_conversation(
    p_type text, p_context uuid, p_initiator uuid, p_recipient uuid, p_title text
) returns uuid
language plpgsql set search_path = '' as $$
declare
    v_id uuid;
begin
    insert into public.conversations (context_type, listing_id, offer_id, repair_id, initiator_id, recipient_id, context_title)
    values (
        p_type,
        case when p_type = 'listing' then p_context end,
        case when p_type = 'offer' then p_context end,
        case when p_type = 'repair' then p_context end,
        p_initiator, p_recipient, left(p_title, 200)
    )
    on conflict do nothing
    returning id into v_id;
    if v_id is null then
        select id into v_id from public.conversations
        where (p_type = 'listing' and listing_id = p_context and initiator_id = p_initiator)
           or (p_type = 'offer' and offer_id = p_context)
           or (p_type = 'repair' and repair_id = p_context);
    end if;
    return v_id;
end;
$$;

create function swapfix_private.post_message(p_conversation uuid, p_sender uuid, p_body text, p_notify boolean) returns uuid
language plpgsql set search_path = '' as $$
declare
    v_conversation public.conversations;
    v_body text := swapfix_private.clean_text(p_body, 'Message', 1, 4000);
    v_recipient uuid;
    v_sender_name text;
    v_id uuid;
begin
    select * into v_conversation from public.conversations where id = p_conversation for update;
    if not found or p_sender not in (v_conversation.initiator_id, v_conversation.recipient_id) then
        perform swapfix_private.fail('SF404', 'Conversation not found.');
    end if;
    insert into public.messages (conversation_id, sender_id, body) values (p_conversation, p_sender, v_body)
    returning id into v_id;
    v_recipient := case when p_sender = v_conversation.initiator_id then v_conversation.recipient_id else v_conversation.initiator_id end;
    update public.conversations set
        last_message_at = now(),
        last_message_preview = left(v_body, 160),
        initiator_unread = initiator_unread + (v_recipient = initiator_id)::integer,
        recipient_unread = recipient_unread + (v_recipient = recipient_id)::integer
    where id = p_conversation;
    if p_notify then
        select display_name into v_sender_name from public.profiles where id = p_sender;
        perform swapfix_private.notify(
            v_recipient, 'message', 'New message from ' || v_sender_name,
            v_conversation.context_title || ': ' || left(v_body, 120),
            '/messages/' || p_conversation, 'conversation', p_conversation
        );
    end if;
    return v_id;
end;
$$;

create function swapfix_private.api_start_listing_inquiry(p_listing_id uuid, p_message text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_profile();
    v_listing public.product_listings;
    v_conversation uuid;
begin
    select * into v_listing from public.product_listings where id = p_listing_id for share;
    if not found or v_listing.status not in ('available', 'reserved') then
        perform swapfix_private.fail('SF404', 'Listing not found.');
    end if;
    if v_listing.owner_id = v_user then
        perform swapfix_private.fail('SF403', 'You cannot send an inquiry to your own listing.');
    end if;
    v_conversation := swapfix_private.ensure_conversation(
        'listing', p_listing_id, v_user, v_listing.owner_id, v_listing.title
    );
    perform swapfix_private.post_message(v_conversation, v_user, p_message, true);
    return jsonb_build_object('conversation_id', v_conversation);
end;
$$;

create function swapfix_private.api_send_message(p_conversation_id uuid, p_body text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_profile();
begin
    return jsonb_build_object('id', swapfix_private.post_message(p_conversation_id, v_user, p_body, true));
end;
$$;

create function swapfix_private.api_mark_conversation_read(p_conversation_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_user();
begin
    update public.conversations set
        initiator_unread = case when initiator_id = v_user then 0 else initiator_unread end,
        recipient_unread = case when recipient_id = v_user then 0 else recipient_unread end
    where id = p_conversation_id and v_user in (initiator_id, recipient_id);
    if not found then
        perform swapfix_private.fail('SF404', 'Conversation not found.');
    end if;
    update public.notifications set read_at = now()
    where recipient_id = v_user and kind = 'message' and related_id = p_conversation_id and read_at is null;
    return jsonb_build_object('id', p_conversation_id);
end;
$$;

-- One round trip for the signed-in shell: stored profile plus unread counts.
create function public.sf_session() returns jsonb
language sql stable security invoker set search_path = '' as $$
    select case when auth.uid() is null then null else jsonb_build_object(
        'user_id', auth.uid(),
        'profile', (
            select to_jsonb(p) || jsonb_build_object(
                'location', coalesce(d.location, ''),
                'email_notifications', coalesce(d.email_notifications, false)
            )
            from public.profiles p
            left join public.profile_private d on d.user_id = p.id
            where p.id = auth.uid()
        ),
        'unread_notifications', (
            select count(*) from public.notifications n where n.recipient_id = auth.uid() and n.read_at is null
        ),
        'unread_messages', (
            select coalesce(sum(case when c.initiator_id = auth.uid() then c.initiator_unread else c.recipient_unread end), 0)
            from public.conversations c
            where auth.uid() in (c.initiator_id, c.recipient_id)
        )
    ) end;
$$;


-- SOURCE: 20261119090600_reviews.sql
-- SwapFix 6/8: reviews. Rating scale is 1 to 5 whole stars; one review per completed repair.

create table public.reviews (
    id uuid primary key default gen_random_uuid(),
    repair_id uuid not null unique references public.repair_requests (id),
    customer_id uuid not null references public.profiles (id),
    technician_id uuid not null references public.technician_profiles (user_id),
    rating smallint not null check (rating between 1 and 5),
    comment text not null default '' check (char_length(comment) <= 2000),
    created_at timestamptz not null default now(),
    constraint reviews_not_self check (customer_id <> technician_id)
);
create index reviews_technician_idx on public.reviews (technician_id, created_at desc);
create index reviews_customer_idx on public.reviews (customer_id, created_at desc);
create trigger reviews_immutable before update on public.reviews
for each row execute function swapfix_private.forbid_update();

create function swapfix_private.api_create_review(p_repair_id uuid, p_rating integer, p_comment text default '') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_profile();
    v_comment text := swapfix_private.clean_text(p_comment, 'Review', 0, 2000);
    v_repair public.repair_requests := swapfix_private.lock_repair_as_customer(p_repair_id, v_user);
    v_id uuid;
begin
    if p_rating is null or p_rating not between 1 and 5 then
        perform swapfix_private.fail('SF422', 'Choose a rating from 1 to 5.');
    end if;
    if v_repair.status <> 'completed' then
        perform swapfix_private.fail('SF409', 'You can review a repair after it is completed.');
    end if;
    -- Serialize reviews for the same technician before INSERT/aggregate. This
    -- separate statement lets the following query see the preceding commit at
    -- READ COMMITTED, even when customers review different repair rows.
    perform 1 from public.technician_profiles where user_id = v_repair.technician_id for update;
    insert into public.reviews (repair_id, customer_id, technician_id, rating, comment)
    values (p_repair_id, v_user, v_repair.technician_id, p_rating, v_comment)
    on conflict (repair_id) do nothing
    returning id into v_id;
    if v_id is null then
        perform swapfix_private.fail('SF409', 'You already reviewed this repair.');
    end if;
    update public.technician_profiles t set
        rating_count = totals.total,
        rating_average = totals.average
    from (
        select count(*)::integer as total, round(avg(rating), 2) as average
        from public.reviews where technician_id = v_repair.technician_id
    ) totals
    where t.user_id = v_repair.technician_id;
    perform swapfix_private.add_repair_event(p_repair_id, v_user, 'review_submitted', v_id, null, '');
    perform swapfix_private.notify(
        v_repair.technician_id, 'review', 'New ' || p_rating || '-star review',
        v_repair.device_brand || ' ' || v_repair.device_model, '/repairs/' || p_repair_id, 'repair', p_repair_id
    );
    return jsonb_build_object('id', v_id);
end;
$$;

-- Public review feed: rating, text, date and reviewer display name only.
-- It never returns repair, customer or device identifiers.
create function swapfix_private.api_public_reviews(p_technician_id uuid, p_limit integer default 20, p_offset integer default 0)
returns table (rating smallint, comment text, created_at timestamptz, reviewer_name text)
language sql stable security definer set search_path = '' as $$
    select r.rating, r.comment, r.created_at, p.display_name
    from public.reviews r
    join public.profiles p on p.id = r.customer_id
    where r.technician_id = p_technician_id
    order by r.created_at desc
    limit least(greatest(coalesce(p_limit, 20), 1), 50)
    offset least(greatest(coalesce(p_offset, 0), 0), 10000);
$$;


-- SOURCE: 20261119090700_storage.sql
-- SwapFix 7/8: storage buckets and object policies.
-- Object names are always <uploader-uuid>/<32-hex>.<ext>.
-- Public buckets are readable by URL. Private buckets are read through short-lived signed URLs,
-- which Storage issues only when the SELECT policies below allow the requesting user.

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values
    ('avatars', 'avatars', true, 5242880, array['image/jpeg', 'image/png', 'image/webp']),
    ('listing-images', 'listing-images', true, 5242880, array['image/jpeg', 'image/png', 'image/webp']),
    ('repair-images', 'repair-images', false, 5242880, array['image/jpeg', 'image/png', 'image/webp']),
    ('offer-images', 'offer-images', false, 5242880, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do update set
    public = excluded.public,
    file_size_limit = excluded.file_size_limit,
    allowed_mime_types = excluded.allowed_mime_types;

-- Starter policy names, in case an earlier starter script was applied to this project.
drop policy if exists swapfix_images_insert_own on storage.objects;
drop policy if exists swapfix_images_select_own on storage.objects;
drop policy if exists swapfix_images_delete_own on storage.objects;

create policy swapfix_objects_insert_own on storage.objects for insert to authenticated
with check (
    bucket_id in ('avatars', 'listing-images', 'repair-images', 'offer-images')
    and (storage.foldername(name))[1] = (select auth.uid())::text
    and name ~ '^[0-9a-f-]{36}/[a-f0-9]{32}\.(jpg|png|webp)$'
);

create policy swapfix_objects_select_own on storage.objects for select to authenticated
using (
    bucket_id in ('avatars', 'listing-images', 'repair-images', 'offer-images')
    and (storage.foldername(name))[1] = (select auth.uid())::text
);

-- repair_requests RLS limits this to the job's customer and technician.
create policy swapfix_repair_objects_select_participant on storage.objects for select to authenticated
using (
    bucket_id = 'repair-images'
    and exists (select 1 from public.repair_requests r where r.photo_paths @> array[storage.objects.name])
);

-- trade_offer_terms RLS limits this to the offer's two parties.
create policy swapfix_offer_objects_select_participant on storage.objects for select to authenticated
using (
    bucket_id = 'offer-images'
    and exists (select 1 from public.trade_offer_terms t where t.photo_paths @> array[storage.objects.name])
);

-- Photos attached to a repair or offer are part of its record and cannot be deleted.
create policy swapfix_objects_delete_own on storage.objects for delete to authenticated
using (
    bucket_id in ('avatars', 'listing-images', 'repair-images', 'offer-images')
    and (storage.foldername(name))[1] = (select auth.uid())::text
    and not (bucket_id = 'repair-images'
             and exists (select 1 from public.repair_requests r where r.photo_paths @> array[storage.objects.name]))
    and not (bucket_id = 'offer-images'
             and exists (select 1 from public.trade_offer_terms t where t.photo_paths @> array[storage.objects.name]))
);


-- SOURCE: 20261119090800_access_control.sql
-- SwapFix 8/8: RLS policies, explicit grants and the generated public RPC wrappers.
-- Only SwapFix objects are touched here, so unrelated tables in the project stay as they are.

do $$
declare
    v_table text;
begin
    foreach v_table in array array[
        'profiles', 'profile_private', 'technician_profiles', 'notifications', 'mail_outbox',
        'product_listings', 'exchange_listings', 'trade_offers', 'trade_offer_terms', 'trade_offer_events',
        'repair_services', 'repair_requests', 'repair_quotations', 'repair_added_costs', 'repair_events',
        'conversations', 'messages', 'reviews'
    ] loop
        execute format('alter table public.%I enable row level security', v_table);
        -- Hosted projects grant new tables to the API roles by default; start from nothing.
        execute format('revoke all on public.%I from public, anon, authenticated, service_role', v_table);
    end loop;
end;
$$;

grant select on public.profiles, public.technician_profiles, public.repair_services,
    public.product_listings, public.exchange_listings to anon, authenticated;
grant select on public.profile_private, public.notifications, public.trade_offers, public.trade_offer_terms,
    public.trade_offer_events, public.repair_requests, public.repair_quotations, public.repair_added_costs,
    public.repair_events, public.conversations, public.messages, public.reviews to authenticated;
-- public.mail_outbox has no grants and no policies: it is reachable only by the worker functions.

create policy profiles_public_read on public.profiles for select to anon, authenticated using (true);
create policy profile_private_own on public.profile_private for select to authenticated
    using (user_id = (select auth.uid()));
create policy technician_profiles_public_read on public.technician_profiles for select to anon, authenticated using (true);
create policy notifications_own on public.notifications for select to authenticated
    using (recipient_id = (select auth.uid()));

create policy listings_public_read on public.product_listings for select to anon, authenticated
    using (status in ('available', 'reserved'));
create policy listings_owner_read on public.product_listings for select to authenticated
    using (owner_id = (select auth.uid()));
create policy listings_inquirer_read on public.product_listings for select to authenticated
    using (exists (
        select 1 from public.conversations c
        where c.listing_id = product_listings.id and c.initiator_id = (select auth.uid())
    ));

create policy exchanges_public_read on public.exchange_listings for select to anon, authenticated
    using (status in ('open', 'agreed'));
create policy exchanges_owner_read on public.exchange_listings for select to authenticated
    using (owner_id = (select auth.uid()));
create policy exchanges_offerer_read on public.exchange_listings for select to authenticated
    using (exists (
        select 1 from public.trade_offers o
        where o.exchange_id = exchange_listings.id and o.offerer_id = (select auth.uid())
    ));

create policy offers_participant_read on public.trade_offers for select to authenticated
    using ((select auth.uid()) in (offerer_id, owner_id));
create policy offer_terms_participant_read on public.trade_offer_terms for select to authenticated
    using (exists (
        select 1 from public.trade_offers o
        where o.id = trade_offer_terms.offer_id and (select auth.uid()) in (o.offerer_id, o.owner_id)
    ));
create policy offer_events_participant_read on public.trade_offer_events for select to authenticated
    using (exists (
        select 1 from public.trade_offers o
        where o.id = trade_offer_events.offer_id and (select auth.uid()) in (o.offerer_id, o.owner_id)
    ));

create policy services_public_read on public.repair_services for select to anon, authenticated using (is_active);
create policy services_owner_read on public.repair_services for select to authenticated
    using (technician_id = (select auth.uid()));

create policy repairs_participant_read on public.repair_requests for select to authenticated
    using ((select auth.uid()) in (customer_id, technician_id));
create policy quotations_participant_read on public.repair_quotations for select to authenticated
    using (exists (
        select 1 from public.repair_requests r
        where r.id = repair_quotations.repair_id and (select auth.uid()) in (r.customer_id, r.technician_id)
    ));
create policy added_costs_participant_read on public.repair_added_costs for select to authenticated
    using (exists (
        select 1 from public.repair_requests r
        where r.id = repair_added_costs.repair_id and (select auth.uid()) in (r.customer_id, r.technician_id)
    ));
create policy repair_events_participant_read on public.repair_events for select to authenticated
    using (exists (
        select 1 from public.repair_requests r
        where r.id = repair_events.repair_id and (select auth.uid()) in (r.customer_id, r.technician_id)
    ));

create policy conversations_participant_read on public.conversations for select to authenticated
    using ((select auth.uid()) in (initiator_id, recipient_id));
create policy messages_participant_read on public.messages for select to authenticated
    using (exists (
        select 1 from public.conversations c
        where c.id = messages.conversation_id and (select auth.uid()) in (c.initiator_id, c.recipient_id)
    ));

-- Public profiles read reviews through sf_public_reviews, which omits private identifiers.
create policy reviews_participant_read on public.reviews for select to authenticated
    using ((select auth.uid()) in (customer_id, technician_id));

-- Generate one SECURITY INVOKER public.sf_<name> wrapper for each private api_<name> function.
do $$
declare
    v_function record;
    v_arguments text;
begin
    for v_function in
        select p.oid, p.proname, p.pronargs, p.proargnames, p.provolatile
        from pg_catalog.pg_proc p
        join pg_catalog.pg_namespace n on n.oid = p.pronamespace
        where n.nspname = 'swapfix_private' and p.proname like 'api\_%'
    loop
        select coalesce(string_agg(format('%1$I => %1$I', name), ', ' order by position), '') into v_arguments
        from unnest(v_function.proargnames[1:v_function.pronargs]) with ordinality as a(name, position);
        execute format(
            'create function public.%I(%s) returns %s language sql %s security invoker set search_path = '''' as %L',
            'sf_' || substr(v_function.proname, 5),
            pg_catalog.pg_get_function_arguments(v_function.oid),
            pg_catalog.pg_get_function_result(v_function.oid),
            case v_function.provolatile when 's' then 'stable' else 'volatile' end,
            format('select * from swapfix_private.%I(%s)', v_function.proname, v_arguments)
        );
    end loop;
end;
$$;

-- Execute privileges: nothing by default, then the narrow audiences below.
do $$
declare
    v_function record;
    v_audience text;
begin
    for v_function in
        select p.oid::regprocedure as signature, n.nspname, p.proname
        from pg_catalog.pg_proc p
        join pg_catalog.pg_namespace n on n.oid = p.pronamespace
        where n.nspname = 'swapfix_private' or (n.nspname = 'public' and p.proname like 'sf\_%')
    loop
        execute format('revoke all on function %s from public, anon, authenticated, service_role', v_function.signature);
        v_audience := case
            when v_function.proname in ('like_pattern', 'prefix_tsquery', 'api_public_reviews',
                                        'sf_public_reviews', 'sf_search_listings', 'sf_search_exchanges', 'sf_search_technicians')
                then 'anon, authenticated'
            when v_function.proname in ('api_mail_claim', 'api_mail_mark', 'sf_mail_claim', 'sf_mail_mark')
                then 'service_role'
            when v_function.proname like 'api\_%' or v_function.proname like 'sf\_%'
                then 'authenticated'
        end;
        if v_audience is not null then
            execute format('grant execute on function %s to %s', v_function.signature, v_audience);
        end if;
    end loop;
end;
$$;


-- SOURCE: 20261119090900_exchange_agreement_version.sql
-- Bind handover actions to the accepted offer shown when the form was rendered.
-- Keep the original RPC signatures available while the browser application rolls out.
create function swapfix_private.require_expected_agreement(
    p_exchange_id uuid, p_expected_offer_id uuid, p_owner_only boolean
) returns void
language plpgsql security invoker set search_path = '' as $$
declare
    v_user uuid := swapfix_private.require_profile();
    v_exchange public.exchange_listings;
begin
    -- Lock the exchange before touching any offers, as in the existing mutations.
    select * into v_exchange from public.exchange_listings where id = p_exchange_id for update;
    if not found or (v_exchange.owner_id <> v_user and (p_owner_only or not exists (
        select 1 from public.trade_offers
        where id = v_exchange.accepted_offer_id and offerer_id = v_user
    ))) then
        perform swapfix_private.fail('SF404', 'Exchange listing not found.');
    end if;
    if p_expected_offer_id is null or v_exchange.status <> 'agreed'
        or v_exchange.accepted_offer_id is distinct from p_expected_offer_id then
        perform swapfix_private.fail('SF409', 'This agreement changed. Refresh and try again.');
    end if;
end;
$$;

create function swapfix_private.api_complete_exchange(p_exchange_id uuid, p_expected_offer_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
    perform swapfix_private.require_expected_agreement(p_exchange_id, p_expected_offer_id, true);
    return swapfix_private.api_complete_exchange(p_exchange_id);
end;
$$;

create function swapfix_private.api_cancel_agreement(p_exchange_id uuid, p_note text, p_expected_offer_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
    perform swapfix_private.require_expected_agreement(p_exchange_id, p_expected_offer_id, false);
    return swapfix_private.api_cancel_agreement(p_exchange_id, p_note);
end;
$$;

create function public.sf_complete_exchange(p_exchange_id uuid, p_expected_offer_id uuid) returns jsonb
language sql security invoker set search_path = '' as $$
    select swapfix_private.api_complete_exchange(p_exchange_id, p_expected_offer_id);
$$;

create function public.sf_cancel_agreement(p_exchange_id uuid, p_note text, p_expected_offer_id uuid) returns jsonb
language sql security invoker set search_path = '' as $$
    select swapfix_private.api_cancel_agreement(p_exchange_id, p_note, p_expected_offer_id);
$$;

revoke all on function swapfix_private.require_expected_agreement(uuid, uuid, boolean),
    swapfix_private.api_complete_exchange(uuid, uuid), swapfix_private.api_cancel_agreement(uuid, text, uuid),
    public.sf_complete_exchange(uuid, uuid), public.sf_cancel_agreement(uuid, text, uuid)
    from public, anon, authenticated, service_role;

grant execute on function swapfix_private.api_complete_exchange(uuid, uuid),
    swapfix_private.api_cancel_agreement(uuid, text, uuid),
    public.sf_complete_exchange(uuid, uuid), public.sf_cancel_agreement(uuid, text, uuid)
    to authenticated;

notify pgrst, 'reload schema';


notify pgrst, 'reload schema';
commit;

-- Verification: the 18 SwapFix tables and their RLS status.
select tablename, rowsecurity from pg_tables
where schemaname = 'public' and tablename in ('profiles', 'profile_private', 'technician_profiles', 'notifications', 'mail_outbox', 'product_listings', 'exchange_listings', 'trade_offers', 'trade_offer_terms', 'trade_offer_events', 'repair_services', 'repair_requests', 'repair_quotations', 'repair_added_costs', 'repair_events', 'conversations', 'messages', 'reviews')
order by tablename;
